import { useState, useEffect } from "react";
import {
  Award,
  Trophy,
  Sparkles,
  BookOpen,
  FileCheck,
  CheckCircle2,
  AlertCircle,
} from "lucide-react";
import { Card, Spinner } from "@/components/ui";
import { getLeaderboardAction } from "@/actions/dashboard/leaderboard";
import type {
  LeaderboardData,
  LeaderboardQueryParams,
} from "@/types/dashboard";

interface LeaderboardViewProps {
  initialData?: LeaderboardData;
  batches?: { id: string; name: string }[];
  userRole?: string;
  defaultBatchId?: string;
}

export function LeaderboardView({
  initialData,
  batches = [],
  userRole,
  defaultBatchId,
}: LeaderboardViewProps) {
  const [scope, setScope] = useState<"batch" | "institute">(
    userRole === "PARENT" || userRole === "STUDENT" ? "batch" : "institute",
  );
  const [period, setPeriod] = useState<"weekly" | "monthly" | "alltime">(
    "alltime",
  );
  const [selectedBatchId, setSelectedBatchId] = useState<string>(
    defaultBatchId || batches[0]?.id || "",
  );

  const [data, setData] = useState<LeaderboardData | undefined>(initialData);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const canSelectInstitute =
    userRole === "INSTITUTE" || userRole === "TEACHER" || userRole === "ADMIN";

  // When switching to batch scope, auto-select first batch if none selected
  useEffect(() => {
    if (scope === "batch" && !selectedBatchId && batches.length > 0) {
      setSelectedBatchId(batches[0].id);
    }
  }, [scope, batches, selectedBatchId]);

  // Fetch leaderboard data when scope, period, or selectedBatchId changes
  useEffect(() => {
    async function loadLeaderboard() {
      const isRestrictedRole = userRole === "STUDENT" || userRole === "PARENT";

      if (scope === "batch" && !selectedBatchId) {
        if (batches.length > 0) {
          return;
        }
        if (isRestrictedRole) {
          setData(undefined);
          setError(
            "No batch assigned to your account yet. Standings will be available once you are assigned to a batch.",
          );
          return;
        }
      }

      setLoading(true);
      setError(null);

      const effectiveScope =
        scope === "batch" && !selectedBatchId && !isRestrictedRole
          ? "institute"
          : scope;

      const params: LeaderboardQueryParams = {
        scope: effectiveScope,
        period,
        ...(effectiveScope === "batch" && selectedBatchId
          ? { batchId: selectedBatchId }
          : {}),
      };

      const res = await getLeaderboardAction(params);
      if (res.ok) {
        setData(res.data);
      } else {
        setError(res.error || "Failed to load leaderboard");
      }
      setLoading(false);
    }

    loadLeaderboard();
  }, [scope, period, selectedBatchId, userRole]);

  const top3 = data?.entries?.slice(0, 3) || [];

  return (
    <div className="mx-auto w-full max-w-5xl space-y-4 sm:space-y-6">
      {/* Header & Controls */}
      <Card className="p-4 sm:p-5">
        <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
          <div>
            <div className="flex items-center gap-2">
              <Sparkles className="h-5 w-5 shrink-0 text-gold-500" />
              <h1 className="font-display text-xl font-bold text-night-900 sm:text-2xl">
                Live Leaderboard
              </h1>
            </div>
            <p className="mt-1 text-xs leading-relaxed text-ink-soft">
              Real-time point rankings. Tiebreak chain: Points &rarr; Lessons
              &rarr; On-time Homework &rarr; Attendance.
            </p>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            {/* Scope selection */}
            {canSelectInstitute && (
              <div className="flex rounded-lg bg-cream-100 p-1 text-xs font-semibold">
                <button
                  type="button"
                  onClick={() => setScope("institute")}
                  className={`rounded-md px-2.5 py-1 transition-all ${
                    scope === "institute"
                      ? "bg-white font-bold text-night-900 shadow-sm"
                      : "text-ink-soft hover:text-night-900"
                  }`}
                >
                  Institute-wise
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setScope("batch");
                    if (!selectedBatchId && batches.length > 0) {
                      setSelectedBatchId(batches[0].id);
                    }
                  }}
                  className={`rounded-md px-2.5 py-1 transition-all ${
                    scope === "batch"
                      ? "bg-white font-bold text-night-900 shadow-sm"
                      : "text-ink-soft hover:text-night-900"
                  }`}
                >
                  Batch-wise
                </button>
              </div>
            )}

            {/* Batch selector dropdown */}
            {scope === "batch" && batches.length > 0 && (
              <select
                value={selectedBatchId}
                onChange={(e) => setSelectedBatchId(e.target.value)}
                className="h-8 rounded-lg border border-cream-200 bg-white px-2.5 text-xs font-semibold text-night-900 shadow-sm focus:outline-none"
              >
                {batches.map((b) => (
                  <option key={b.id} value={b.id}>
                    {b.name}
                  </option>
                ))}
              </select>
            )}

            {/* Period selector */}
            <div className="flex rounded-lg bg-cream-100 p-1 text-xs font-semibold">
              {(["weekly", "monthly", "alltime"] as const).map((p) => (
                <button
                  key={p}
                  type="button"
                  onClick={() => setPeriod(p)}
                  className={`rounded-md px-2.5 py-1 capitalize transition-all ${
                    period === p
                      ? "bg-white font-bold text-night-900 shadow-sm"
                      : "text-ink-soft hover:text-night-900"
                  }`}
                >
                  {p}
                </button>
              ))}
            </div>
          </div>
        </div>
      </Card>

      {loading ? (
        <div className="flex justify-center py-16">
          <Spinner />
        </div>
      ) : error ? (
        <Card className="flex flex-col items-center gap-2 py-12 text-center text-sm text-ink-soft">
          <AlertCircle className="h-6 w-6 text-amber-600" />
          <p className="max-w-sm font-semibold text-night-900">{error}</p>
        </Card>
      ) : !data || !data.entries || data.entries.length === 0 ? (
        <Card className="py-12 text-center text-sm text-ink-soft">
          No leaderboard entries found for this batch/period.
        </Card>
      ) : (
        <>
          {/* Top 3 Podium (Optimized for Mobile Side-by-Side) */}
          {top3.length > 0 && (
            <div className="grid grid-cols-3 items-end gap-2 pt-2 pb-1 sm:gap-4">
              {/* Rank 2 (Silver) - Left */}
              <div className="flex min-h-[130px] flex-col items-center justify-end rounded-xl border border-slate-200 bg-slate-50/70 p-2.5 text-center shadow-sm sm:min-h-[160px] sm:p-4">
                <div className="relative mb-1.5 flex h-10 w-10 items-center justify-center rounded-full bg-slate-200 font-display text-sm font-bold text-slate-800 shadow-inner sm:h-12 sm:w-12 sm:text-base">
                  2
                  <Award className="absolute -top-1 -right-1 h-4 w-4 text-slate-500" />
                </div>
                <h3 className="max-w-full truncate font-display text-xs font-bold text-night-900 sm:text-base">
                  {top3[1]?.name || "—"}
                </h3>
                <p className="mt-0.5 text-xs font-extrabold text-slate-700 sm:text-lg">
                  {top3[1]?.points ?? 0}{" "}
                  <span className="text-[10px] font-normal text-ink-soft">
                    pts
                  </span>
                </p>
              </div>

              {/* Rank 1 (Gold) - Center */}
              <div className="flex min-h-[145px] -translate-y-1 transform flex-col items-center justify-end rounded-xl border-2 border-gold-500/50 bg-gold-500/10 p-3 text-center shadow-md sm:min-h-[180px] sm:-translate-y-2 sm:p-5">
                <div className="relative mb-2 flex h-12 w-12 items-center justify-center rounded-full bg-gold-500 font-display text-base font-black text-night-900 shadow-md sm:h-16 sm:w-16 sm:text-xl">
                  1
                  <Trophy className="absolute -top-1.5 -right-1.5 h-5 w-5 animate-bounce text-amber-700 sm:h-6 sm:w-6" />
                </div>
                <h3 className="max-w-full truncate font-display text-xs font-extrabold text-night-900 sm:text-lg">
                  {top3[0]?.name || "—"}
                </h3>
                <p className="text-gold-700 mt-0.5 text-sm font-black sm:text-xl">
                  {top3[0]?.points ?? 0}{" "}
                  <span className="text-[10px] font-normal text-ink-soft">
                    pts
                  </span>
                </p>
              </div>

              {/* Rank 3 (Bronze) - Right */}
              <div className="flex min-h-[130px] flex-col items-center justify-end rounded-xl border border-amber-200 bg-amber-50/50 p-2.5 text-center shadow-sm sm:min-h-[160px] sm:p-4">
                <div className="relative mb-1.5 flex h-10 w-10 items-center justify-center rounded-full bg-amber-200 font-display text-sm font-bold text-amber-900 shadow-inner sm:h-12 sm:w-12 sm:text-base">
                  3
                  <Award className="absolute -top-1 -right-1 h-4 w-4 text-amber-700" />
                </div>
                <h3 className="max-w-full truncate font-display text-xs font-bold text-night-900 sm:text-base">
                  {top3[2]?.name || "—"}
                </h3>
                <p className="mt-0.5 text-xs font-extrabold text-amber-800 sm:text-lg">
                  {top3[2]?.points ?? 0}{" "}
                  <span className="text-[10px] font-normal text-ink-soft">
                    pts
                  </span>
                </p>
              </div>
            </div>
          )}

          {/* Full Rankings Table */}
          <Card className="overflow-hidden border border-cream-200 p-0 shadow-soft">
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs sm:text-sm">
                <thead className="bg-cream-100 font-display text-[11px] font-semibold text-night-900 sm:text-xs">
                  <tr>
                    <th className="px-3 py-3 sm:px-4">Rank</th>
                    <th className="px-3 py-3 sm:px-4">Student</th>
                    <th className="px-3 py-3 text-center sm:px-4">Points</th>
                    <th className="px-3 py-3 text-center sm:px-4">Breakdown</th>
                    <th className="hidden px-3 py-3 text-center sm:table-cell sm:px-4">
                      Tiebreaks
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-cream-200 bg-white">
                  {data.entries.map((entry) => (
                    <tr
                      key={entry.studentId}
                      className={`transition-colors hover:bg-cream-50 ${
                        entry.isCurrentUser ? "bg-gold-500/15 font-bold" : ""
                      }`}
                    >
                      <td className="px-3 py-3 font-bold whitespace-nowrap sm:px-4">
                        <span
                          className={`inline-flex h-6 w-6 items-center justify-center rounded-full text-[11px] sm:h-7 sm:w-7 sm:text-xs ${
                            entry.rank === 1
                              ? "bg-gold-500 font-black text-night-900"
                              : entry.rank === 2
                                ? "bg-slate-200 text-slate-800"
                                : entry.rank === 3
                                  ? "bg-amber-100 text-amber-800"
                                  : "bg-cream-100 text-ink-soft"
                          }`}
                        >
                          #{entry.rank}
                        </span>
                      </td>
                      <td className="px-3 py-3 whitespace-nowrap sm:px-4">
                        <div className="flex items-center gap-1.5">
                          <span className="font-semibold text-night-900">
                            {entry.name}
                          </span>
                          {entry.isCurrentUser && (
                            <span className="rounded-full bg-gold-500 px-1.5 py-0.5 text-[9px] font-extrabold text-night-900 sm:text-[10px]">
                              YOU
                            </span>
                          )}
                        </div>
                      </td>
                      <td className="px-3 py-3 text-center whitespace-nowrap sm:px-4">
                        <span className="text-sm font-extrabold text-night-900 sm:text-base">
                          {entry.points}
                        </span>
                      </td>
                      <td className="px-3 py-3 text-center text-[11px] whitespace-nowrap text-ink-soft sm:px-4">
                        <div className="flex items-center justify-center gap-2 sm:gap-3">
                          <span
                            title="Lesson Points"
                            className="text-gold-700 flex items-center gap-0.5 font-medium"
                          >
                            <BookOpen className="h-3 w-3" />
                            {entry.breakdown?.lessonPoints ?? 0}
                          </span>
                          <span
                            title="Homework Points"
                            className="flex items-center gap-0.5 font-medium text-arabic"
                          >
                            <FileCheck className="h-3 w-3" />
                            {entry.breakdown?.homeworkPoints ?? 0}
                          </span>
                          <span
                            title="Attendance Points"
                            className="flex items-center gap-0.5 font-medium text-quran"
                          >
                            <CheckCircle2 className="h-3 w-3" />
                            {entry.breakdown?.attendancePoints ?? 0}
                          </span>
                        </div>
                      </td>
                      <td className="hidden px-3 py-3 text-center text-xs whitespace-nowrap text-ink-soft sm:table-cell sm:px-4">
                        <span>
                          Lessons: {entry.tiebreak?.lessonsCompleted ?? 0} | HW:{" "}
                          {entry.tiebreak?.homeworkOnTime ?? 0} | Att:{" "}
                          {entry.tiebreak?.attendanceCount ?? 0}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </Card>
        </>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import {
  Trophy,
  Award,
  Sparkles,
  Lock,
  Users,
  ChevronRight,
  ArrowRight,
  Filter,
  CheckCircle2,
  AlertCircle,
  Calendar,
  Zap,
} from "lucide-react";
import { Card, Button, Spinner } from "@/components/ui";
import {
  getLeaderboardAction,
  getFinalLeaderboardAction,
} from "@/actions/dashboard/leaderboard";
import type {
  ParentChildOverviewItem,
  LeaderboardData,
  LeaderboardQueryParams,
  FinalLeaderboardData,
} from "@/types/dashboard";

interface ParentHomeViewProps {
  childrenData: ParentChildOverviewItem[];
}

export function ParentHomeView({ childrenData }: ParentHomeViewProps) {
  // Extract unique batches from children
  const availableBatches = Array.from(
    new Map(
      childrenData
        .filter((c) => c.batch?.id && c.batch?.name)
        .map((c) => [c.batch.id, c.batch]),
    ).values(),
  );

  const [selectedBatchId, setSelectedBatchId] = useState<string>(
    availableBatches[0]?.id || "",
  );
  const [activeTab, setActiveTab] = useState<"live" | "final">("live");
  const [period, setPeriod] = useState<"weekly" | "monthly" | "alltime">(
    "alltime",
  );

  // Live leaderboard state
  const [liveData, setLiveData] = useState<LeaderboardData | null>(null);
  const [loadingLive, setLoadingLive] = useState(false);
  const [liveError, setLiveError] = useState<string | null>(null);

  // Final leaderboard state
  const [finalData, setFinalData] = useState<FinalLeaderboardData | null>(null);
  const [loadingFinal, setLoadingFinal] = useState(false);
  const [finalError, setFinalError] = useState<string | null>(null);

  // Parent children IDs for highlighting
  const parentChildIds = new Set(childrenData.map((c) => c.id));
  const parentChildCodes = new Set(childrenData.map((c) => c.studentCode));

  // Fetch Live Leaderboard: GET /leaderboard?scope=batch&period=...&batchId=...
  useEffect(() => {
    if (activeTab !== "live") return;

    async function loadLiveLeaderboard() {
      if (!selectedBatchId && availableBatches.length > 0) {
        setSelectedBatchId(availableBatches[0].id);
        return;
      }

      setLoadingLive(true);
      setLiveError(null);

      const params: LeaderboardQueryParams = {
        scope: "batch",
        period,
        ...(selectedBatchId ? { batchId: selectedBatchId } : {}),
      };

      const res = await getLeaderboardAction(params);
      if (res.ok) {
        setLiveData(res.data);
      } else {
        setLiveError(res.error || "Could not load live leaderboard");
      }
      setLoadingLive(false);
    }

    loadLiveLeaderboard();
  }, [activeTab, selectedBatchId, period]);

  // Fetch Final Leaderboard: GET /batches/:id/final-leaderboard
  useEffect(() => {
    if (activeTab !== "final") return;

    async function loadFinalLeaderboard() {
      if (!selectedBatchId) {
        setFinalError("Please select a batch to view final standings.");
        return;
      }

      setLoadingFinal(true);
      setFinalError(null);

      const res = await getFinalLeaderboardAction(selectedBatchId);
      if (res.ok) {
        setFinalData(res.data);
      } else {
        setFinalError(
          res.error ||
            "No final frozen leaderboard available for this batch yet.",
        );
      }
      setLoadingFinal(false);
    }

    loadFinalLeaderboard();
  }, [activeTab, selectedBatchId]);

  const selectedBatchName =
    availableBatches.find((b) => b.id === selectedBatchId)?.name || "Batch";

  const top3Live = liveData?.entries?.slice(0, 3) || [];
  const restLive = liveData?.entries?.slice(3) || [];

  return (
    <div className="mx-auto w-full max-w-5xl space-y-8">
      {/* Header Banner */}
      <div className="relative overflow-hidden rounded-2xl bg-gradient-to-r from-night-900 via-night-800 to-night-900 p-6 text-cream-50 shadow-soft sm:p-8">
        <div className="relative z-10 max-w-2xl space-y-2">
          <div className="inline-flex items-center gap-2 rounded-full border border-gold-500/30 bg-gold-500/20 px-3 py-1 text-xs font-semibold text-gold-400">
            <Sparkles className="h-3.5 w-3.5" />
            <span>Parent Dashboard</span>
          </div>
          <h1 className="font-display text-2xl font-extrabold tracking-tight text-white sm:text-3xl">
            Academic Standings & Leaderboard
          </h1>
          <p className="text-sm leading-relaxed text-cream-100/70">
            Monitor real-time progress, live batch rankings, and frozen final
            standings for your children.
          </p>
        </div>

        {/* Decorative backdrop elements */}
        <div className="pointer-events-none absolute -right-8 -bottom-8 h-48 w-48 rounded-full bg-gold-500/10 blur-2xl" />
      </div>

      {/* Children Overview Section */}
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="flex items-center gap-2 font-display text-lg font-bold text-night-900">
            <Users className="h-5 w-5 text-gold-600" />
            <span>Enrolled Children ({childrenData.length})</span>
          </h2>
          <Link
            href="/dashboard/parent/children"
            className="hover:text-gold-700 flex items-center gap-1 text-xs font-bold text-gold-600 transition-colors"
          >
            Manage All <ArrowRight className="h-3.5 w-3.5" />
          </Link>
        </div>

        {childrenData.length === 0 ? (
          <Card className="py-10 text-center text-sm text-ink-soft">
            No children are currently linked to your parent account.
          </Card>
        ) : (
          <div className="grid gap-3 sm:grid-cols-2 md:grid-cols-3">
            {childrenData.map((child) => {
              const isSelected = child.batch?.id === selectedBatchId;

              return (
                <Card
                  key={child.id}
                  className={`flex flex-col justify-between space-y-3 border p-4 transition-all ${
                    isSelected
                      ? "border-gold-500/60 bg-gold-500/5 shadow-sm ring-1 ring-gold-500/20"
                      : "hover:border-cream-300 border-cream-200 bg-white hover:shadow-sm"
                  }`}
                >
                  <div className="flex items-start justify-between gap-2">
                    <div className="flex min-w-0 items-center gap-2.5">
                      <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-duas-soft font-display text-base font-bold text-duas shadow-inner">
                        {child.name.charAt(0).toUpperCase()}
                      </div>
                      <div className="min-w-0">
                        <h3 className="truncate font-display text-sm font-bold text-night-900">
                          {child.name}
                        </h3>
                        <p className="truncate text-[11px] text-ink-soft">
                          {child.studentCode} • Class {child.class}
                        </p>
                      </div>
                    </div>

                    <span className="inline-flex shrink-0 items-center gap-1 rounded-full bg-gold-500/10 px-2 py-0.5 text-xs font-extrabold text-night-900">
                      <Trophy className="h-3 w-3 text-gold-600" />
                      <span>#{child.rank?.rank ?? "-"}</span>
                    </span>
                  </div>

                  <div className="flex items-center justify-between border-t border-b border-cream-100/70 py-2 text-xs">
                    <span className="truncate text-ink-soft">
                      Batch:{" "}
                      <strong className="text-night-900">
                        {child.batch?.name || "Unassigned"}
                      </strong>
                    </span>
                    <span className="shrink-0 font-extrabold text-night-900">
                      {child.points} Pts
                    </span>
                  </div>

                  <div className="flex items-center justify-between pt-1">
                    {child.batch?.id ? (
                      <button
                        type="button"
                        onClick={() => setSelectedBatchId(child.batch.id)}
                        className={`text-[11px] font-bold transition-colors ${
                          isSelected
                            ? "font-extrabold text-gold-600"
                            : "text-ink-soft hover:text-night-900 hover:underline"
                        }`}
                      >
                        {isSelected ? "Viewing Standings" : "Select Standings"}
                      </button>
                    ) : (
                      <span />
                    )}

                    <Link
                      href={`/dashboard/parent/children/${child.id}`}
                      className="inline-flex items-center gap-0.5 rounded-md bg-cream-100 px-2.5 py-1 text-xs font-bold text-night-900 transition-colors hover:bg-gold-500 hover:text-night-900"
                    >
                      Details <ChevronRight className="h-3 w-3" />
                    </Link>
                  </div>
                </Card>
              );
            })}
          </div>
        )}
      </div>

      {/* Leaderboard Main Section */}
      <Card className="space-y-6 border border-cream-200 p-6 shadow-soft">
        {/* Navigation Tabs & Controls */}
        <div className="flex flex-col gap-4 border-b border-cream-100 pb-5 sm:flex-row sm:items-center sm:justify-between">
          {/* Tab Switcher */}
          <div className="flex w-full rounded-xl bg-cream-100 p-1 text-xs font-bold text-night-900 sm:w-auto">
            <button
              type="button"
              onClick={() => setActiveTab("live")}
              className={`inline-flex flex-1 items-center justify-center gap-1.5 rounded-lg px-4 py-2 transition-all sm:flex-none ${
                activeTab === "live"
                  ? "bg-white font-extrabold text-night-900 shadow-sm"
                  : "text-ink-soft hover:text-night-900"
              }`}
            >
              <Zap className="h-3.5 w-3.5 text-gold-500" />
              <span>Live Leaderboard</span>
            </button>
            <button
              type="button"
              onClick={() => setActiveTab("final")}
              className={`inline-flex flex-1 items-center justify-center gap-1.5 rounded-lg px-4 py-2 transition-all sm:flex-none ${
                activeTab === "final"
                  ? "bg-white font-extrabold text-night-900 shadow-sm"
                  : "text-ink-soft hover:text-night-900"
              }`}
            >
              <Lock className="h-3.5 w-3.5 text-gold-600" />
              <span>Final Standings</span>
            </button>
          </div>

          {/* Controls: Batch & Period Selectors */}
          <div className="flex flex-wrap items-center gap-3">
            {availableBatches.length > 0 && (
              <div className="flex items-center gap-1.5">
                <span className="hidden text-xs font-semibold text-ink-soft sm:inline">
                  Batch:
                </span>
                <select
                  value={selectedBatchId}
                  onChange={(e) => setSelectedBatchId(e.target.value)}
                  className="rounded-lg border border-cream-200 bg-white px-3 py-1.5 text-xs font-semibold text-night-900 outline-none focus:border-gold-500"
                >
                  {availableBatches.map((b) => (
                    <option key={b.id} value={b.id}>
                      {b.name}
                    </option>
                  ))}
                </select>
              </div>
            )}

            {activeTab === "live" && (
              <div className="flex rounded-lg bg-cream-100 p-1 text-xs font-semibold">
