"use client";

import { useEffect, useRef, useState, useTransition } from "react";
import { Search, Check, Loader2, X } from "lucide-react";
import { cn } from "@/lib/utils/cn";

export interface PickerItem {
  id: string;
  /** Main line, e.g. the person's name. */
  title: string;
  /** Secondary line, e.g. "email · phone". */
  subtitle?: string;
}

interface SearchPickerProps {
  label: string;
  placeholder: string;
  /** Runs the search. Debounced by this component. */
  onSearch: (term: string) => Promise<PickerItem[]>;
  selected: PickerItem | null;
  onSelect: (item: PickerItem | null) => void;
  /** Shown under the list when a search returns nothing. */
  emptyAction?: React.ReactNode;
  error?: string;
}

/**
 * A debounced search-and-select field. Used to pick a teacher or an existing
 * parent. Fetches on typing (300ms debounce), shows results, and lets the user
 * clear the selection to search again.
 */
export function SearchPicker({
  label,
  placeholder,
  onSearch,
  selected,
  onSelect,
  emptyAction,
  error,
}: SearchPickerProps) {
  const [term, setTerm] = useState("");
  const [results, setResults] = useState<PickerItem[]>([]);
  const [searched, setSearched] = useState(false);
  const [pending, startTransition] = useTransition();
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Debounced search — runs 300ms after the user stops typing.
  useEffect(() => {
    if (selected) return; // don't search while something is chosen

    if (!term.trim()) {
      setResults([]);
      setSearched(false);
      if (timer.current) clearTimeout(timer.current);
      return;
    }

    if (timer.current) clearTimeout(timer.current);

    timer.current = setTimeout(() => {
      startTransition(async () => {
        const items = await onSearch(term);
        setResults(items);
        setSearched(true);
      });
    }, 300);

    return () => {
      if (timer.current) clearTimeout(timer.current);
    };
    // onSearch is stable in practice (defined in the parent), term drives this
  }, [term, selected, onSearch]);

  // ---- Something is already selected: show it as a chip ----
  if (selected) {
    return (
      <div className="flex flex-col gap-1.5">
        <span className="text-sm font-medium text-night-900">{label}</span>
        <div className="flex items-center justify-between gap-3 rounded-md border border-success/40 bg-success/10 px-4 py-3">
          <div className="min-w-0">
            <p className="truncate font-medium text-night-900">
              {selected.title}
            </p>
            {selected.subtitle && (
              <p className="truncate text-sm text-ink-soft">
                {selected.subtitle}
              </p>
            )}
          </div>
          <button
            type="button"
            onClick={() => {
              onSelect(null);
              setTerm("");
              setSearched(false);
            }}
            className="shrink-0 rounded-full p-1.5 text-ink-soft transition-colors hover:bg-cream-200 hover:text-night-900"
            aria-label={`Change ${label.toLowerCase()}`}
          >
            <X className="h-4 w-4" aria-hidden />
          </button>
        </div>
      </div>
    );
  }

  // ---- Nothing selected yet: search box + results ----
  return (
    <div className="flex flex-col gap-1.5">
      <label
        htmlFor={`picker-${label}`}
        className="text-sm font-medium text-night-900"
      >
        {label}
      </label>

      <div className="relative">
        <Search
          className="pointer-events-none absolute top-1/2 left-3.5 h-[18px] w-[18px] -translate-y-1/2 text-ink-soft"
          aria-hidden
        />
        <input
          id={`picker-${label}`}
          value={term}
          onChange={(e) => setTerm(e.target.value)}
          placeholder={placeholder}
          autoComplete="off"
          className={cn(
            "min-h-[44px] w-full rounded-sm border bg-cream-50 py-2.5 pr-10 pl-11 text-[15px] text-night-900",
            "transition-colors outline-none placeholder:text-ink-soft/60",
            "focus-visible:outline-2 focus-visible:outline-gold-500",
            error ? "border-error" : "border-cream-200",
          )}
          aria-invalid={Boolean(error)}
        />
        {pending && (
          <Loader2
            className="absolute top-1/2 right-3.5 h-4 w-4 -translate-y-1/2 animate-spin text-gold-500"
            aria-hidden
          />
        )}
      </div>

      {error && (
        <p role="alert" className="text-sm text-error">
          {error}
        </p>
      )}

      {/* Results */}
      {results.length > 0 && (
        <ul className="mt-1 max-h-64 divide-y divide-cream-200 overflow-y-auto rounded-md border border-cream-200 bg-cream-50">
          {results.map((item) => (
            <li key={item.id}>
              <button
                type="button"
                onClick={() => onSelect(item)}
                className="flex w-full items-center justify-between gap-3 px-4 py-3 text-left transition-colors hover:bg-cream-100"
              >
                <span className="min-w-0">
                  <span className="block truncate font-medium text-night-900">
                    {item.title}
                  </span>
                  {item.subtitle && (
                    <span className="block truncate text-sm text-ink-soft">
                      {item.subtitle}
                    </span>
                  )}
                </span>
                <Check className="h-4 w-4 shrink-0 text-ink-soft" aria-hidden />
              </button>
            </li>
          ))}
        </ul>
      )}

      {/* Nothing found — offer the fallback action (e.g. "add a new parent") */}
      {searched && !pending && results.length === 0 && (
        <div className="mt-1 rounded-md border border-cream-200 bg-cream-50 px-4 py-4 text-center">
          <p className="text-sm text-ink-soft">
            {term ? `No match for “${term}”.` : "No results yet."}
          </p>
          {emptyAction && <div className="mt-3">{emptyAction}</div>}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { type Homework, type Submission } from "@/types/shared/homework";
import { Button, Card, Input, Textarea, Select } from "@/components/ui";
import { submitStudentHomework } from "@/actions/homework";
import { toast } from "sonner";
import { StatusChip } from "@/components/shared/homework/StatusChip";
import { YouTubeEmbed } from "@/components/shared/homework/YouTubeEmbed";
import { formatCalendarDate } from "@/lib/utils/date";
import {
  ArrowLeft,
  Calendar,
  CheckCircle,
  FileText,
  Image as ImageIcon,
  Link as LinkIcon,
  Plus,
  Trash2,
  AlertTriangle,
  Play,
  Award,
  BookOpen,
  CheckCircle2,
  Clock,
  Sparkles,
  ExternalLink,
} from "lucide-react";
import Link from "next/link";

interface StudentSubmissionFormProps {
  homework: Homework;
  canSubmit: boolean;
  submission: Submission | null;
  submitBlockedReason?: string | null;
}

export function StudentSubmissionForm({
  homework,
  canSubmit,
  submission,
  submitBlockedReason = null,
}: StudentSubmissionFormProps) {
  const router = useRouter();
  const [loading, setLoading] = useState(false);

  // Submit states
  const [note, setNote] = useState("");
  const [attachments, setAttachments] = useState<
    {
      type: "IMAGE" | "PDF" | "YOUTUBE" | "LINK";
      url: string;
      fileName: string | null;
    }[]
  >([]);

  // Local state for adding single attachment
  const [attType, setAttType] = useState<"IMAGE" | "PDF" | "YOUTUBE" | "LINK">(
    "IMAGE",
  );
  const [attUrl, setAttUrl] = useState("");
  const [attName, setAttName] = useState("");
  const [attError, setAttError] = useState<string | null>(null);

  // Simulation upload state
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);

  const handleAddAttachment = () => {
    setAttError(null);

    if (attachments.length >= 10) {
      setAttError("Maximum 10 attachments allowed");
      return;
    }

    if (attType === "IMAGE" || attType === "PDF") {
      if (!attName.trim()) {
        setAttError("Please enter a file name");
        return;
      }
      // Simulate file upload
      setUploading(true);
      setUploadProgress(10);
      const interval = setInterval(() => {
        setUploadProgress((p) => {
          if (p >= 100) {
            clearInterval(interval);
            setTimeout(() => {
              setAttachments((prev) => [
                ...prev,
                {
                  type: attType,
                  url:
                    attType === "IMAGE"
                      ? "https://images.unsplash.com/photo-1577896851231-70ef18881754?w=500&auto=format&fit=crop"
                      : "https://www.w3.org/WAI/ER/tests/xhtml/testfiles/resources/pdf/dummy.pdf",
                  fileName: attName.trim(),
                },
              ]);
              setAttName("");
              setUploading(false);
              toast.success("File uploaded successfully (simulated)");
            }, 300);
            return 100;
          }
          return p + 30;
        });
      }, 150);
    } else {
      if (!attUrl.trim()) {
        setAttError("Please enter a valid URL");
        return;
      }

      if (attType === "YOUTUBE") {
        const id = parseYoutubeId(attUrl);
        if (!id || id.length !== 11) {
          setAttError(
            "Please enter a valid YouTube link (e.g. watch?v=ID or youtu.be/ID)",
          );
          return;
        }
      }

      setAttachments((prev) => [
        ...prev,
        {
          type: attType,
          url: attUrl.trim(),
          fileName:
            attType === "YOUTUBE"
              ? "YouTube Video"
              : attName.trim() || "Web Link",
        },
      ]);
      setAttUrl("");
      setAttName("");
    }
  };

  const handleRemoveAttachment = (idx: number) => {
    setAttachments((prev) => prev.filter((_, i) => i !== idx));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Client-side validations
    if (!note.trim() && attachments.length === 0) {
      toast.error("Please add a note or at least one attachment");
      return;
    }

    if (!homework?.id) {
      toast.error("Invalid homework assignment");
      return;
    }

    setLoading(true);
    const result = await submitStudentHomework(homework.id, {
      note: note.trim() || null,
      attachments,
    });
    setLoading(false);

    if (result.ok) {
      toast.success("Homework submitted successfully!");
      router.refresh();
    } else {
      toast.error(result.error);
    }
  };

  function parseYoutubeId(url: string): string | null {
    try {
      const regExp =
        /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|shorts\/|watch\?v=|\&v=)([^#\&\?]*).*/;
      const match = url.match(regExp);
      return match && match[2].length === 11 ? match[2] : null;
    } catch {
      return null;
    }
  }

  // Formatting date helper
  const formattedDueDate = formatCalendarDate(homework?.dueDate);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-3">
        <Link
          href="/dashboard/student/homework"
          className="mb-3 inline-flex items-center gap-1 text-sm text-ink-soft transition-colors hover:text-night-900"
        >
          <ArrowLeft className="h-4 w-4" />
          <span>Back</span>
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-night-900">
            Assignment Details
          </h1>
          <p className="text-sm text-ink-soft">
            Review homework details and submit your work.
          </p>
        </div>
      </div>

      <div className="grid gap-6 lg:grid-cols-3">
        {/* Left column: Homework card & prompt */}
        <div className="space-y-6 lg:col-span-2">
          <Card className="space-y-4 border border-cream-200 p-6 shadow-soft">
            <div className="flex flex-wrap items-center justify-between gap-2 border-b border-cream-100 pb-3">
              {homework?.batch?.name && (
                <span className="rounded bg-quran-soft px-2.5 py-1 text-xs font-semibold text-quran">
                  {homework.batch.name}
                </span>
              )}
              <span className="flex items-center gap-1 text-xs text-ink-soft">
                <Calendar className="h-3.5 w-3.5" /> Due Date:{" "}
                {homework?.dueDate ? formatCalendarDate(homework.dueDate) : "—"}
              </span>
            </div>

            <h2 className="text-xl font-bold text-night-900">
              {homework?.title || "Homework Details"}
            </h2>

            {/* Clamped show-more instructions */}
            <div className="space-y-2">
              <h4 className="text-xs font-bold tracking-wider text-ink-soft uppercase">
                Instructions
              </h4>
              <div className="rounded-lg border border-cream-200/50 bg-cream-50 p-4 text-sm leading-relaxed whitespace-pre-wrap text-ink">
                {homework?.instruction || "No instructions provided."}
              </div>
            </div>

            {/* Lesson details if linked */}
            {homework?.lesson && (
              <div className="space-y-3 rounded-lg border border-arabic/10 bg-arabic-soft/20 p-4">
                <h4 className="text-xs font-bold tracking-wider text-arabic uppercase">
                  Linked Lesson Reference
                </h4>
                <div className="flex flex-col items-start justify-between gap-4 sm:flex-row sm:items-center">
                  <div className="flex items-center gap-2">
                    <BookOpen className="h-5 w-5 text-arabic" />
                    <span className="text-sm font-semibold text-night-900">
                      {homework.lesson.title || "Lesson"}
                    </span>
                  </div>
                  {homework.lesson.youtubeVideoId && (
                    <a
                      href={`https://www.youtube.com/watch?v=${homework.lesson.youtubeVideoId}`}
                      target="_blank"
                      rel="noreferrer"
                      className="inline-flex items-center gap-1.5 text-xs font-bold text-arabic hover:underline"
                    >
                      View video lesson <Play className="h-3 w-3 fill-arabic" />
                    </a>
                  )}
                </div>
                {homework.lesson.youtubeVideoId && (
                  <YouTubeEmbed
                    url={`https://www.youtube.com/watch?v=${homework.lesson.youtubeVideoId}`}
                    className="mx-auto max-w-md"
                  />
                )}
              </div>
            )}
          </Card>

          {/* Student Work View / Form */}
          {submission ? (
            /* ==================== SUBMISSION PRESENT: STATES 3 & 4 ==================== */
            <Card className="space-y-5 border border-cream-200 p-6 shadow-soft">
              <div className="flex items-center justify-between border-b border-cream-100 pb-3">
                <h3 className="font-bold text-night-900">Your Submission</h3>
                <div className="flex items-center gap-2">
                  <StatusChip
                    chip={
                      submission.status === "GRADED"
                        ? submission.isLate
                          ? "GRADED_LATE"
                          : "GRADED"
                        : submission.isLate
                          ? "SUBMITTED_LATE"
                          : "SUBMITTED"
                    }
                  />
                </div>
              </div>

              {/* Note */}
              {submission.note && (
                <div className="space-y-1">
                  <h4 className="text-xs font-bold tracking-wider text-ink-soft uppercase">
                    My Notes
                  </h4>
                  <p className="rounded-lg border border-cream-200/50 bg-cream-50/30 p-4 text-sm leading-relaxed whitespace-pre-wrap text-ink">
                    {submission.note}
                  </p>
                </div>
              )}

              {/* Attachments */}
              {submission.attachments.length > 0 && (
                <div className="space-y-3">
                  <h4 className="text-xs font-bold tracking-wider text-ink-soft uppercase">
                    My Attachments
                  </h4>
                  <div className="grid gap-4 sm:grid-cols-2">
                    {submission.attachments
                      .sort((a, b) => a.order - b.order)
                      .map((att) => (
                        <div
                          key={att.id}
                          className="flex flex-col gap-2 rounded-lg border border-cream-200 bg-white p-3 shadow-sm"
                        >
                          <div className="mb-1 flex items-center justify-between gap-2 border-b border-cream-100 pb-2">
                            <span className="inline-flex items-center gap-1.5 text-xs font-semibold text-ink-soft">
                              {att.type === "IMAGE" && (
                                <ImageIcon className="h-3.5 w-3.5 text-success" />
                              )}
                              {att.type === "PDF" && (
                                <FileText className="h-3.5 w-3.5 text-error" />
                              )}
                              {att.type === "YOUTUBE" && (
                                <LinkIcon className="h-3.5 w-3.5 text-studies" />
                              )}
                              {att.type === "LINK" && (
                                <ExternalLink className="h-3.5 w-3.5 text-arabic" />
                              )}
                              {att.type}
                            </span>
                            <a
                              href={att.url}
                              target="_blank"
                              rel="noreferrer"
                              className="flex items-center gap-1 text-xs font-bold text-quran hover:underline"
                            >
                              Open <ExternalLink className="h-3 w-3" />
                            </a>
                          </div>

                          {att.type === "IMAGE" && (
                            <div className="relative aspect-video w-full overflow-hidden rounded border bg-cream-50">
                              <img
                                src={att.url}
                                alt={att.fileName || "Uploaded file"}
                                className="h-full w-full object-cover"
                              />
                            </div>
                          )}

                          {att.type === "YOUTUBE" && (
                            <YouTubeEmbed url={att.url} />
                          )}

                          {att.fileName && (
                            <span className="text-xs font-medium break-all text-night-900">
                              {att.fileName}
                            </span>
                          )}
                        </div>
                      ))}
                  </div>
                </div>
              )}
            </Card>
          ) : canSubmit ? (
            /* ==================== STATE 1: ACTIVE SUBMIT FORM ==================== */
            <form onSubmit={handleSubmit} className="space-y-6">
              <Card className="space-y-5 border border-cream-200 p-6 shadow-soft">
                <div className="flex items-center justify-between border-b border-cream-100 pb-3">
                  <h3 className="flex items-center gap-2 font-bold text-night-900">
                    <Sparkles className="h-5 w-5 text-gold-500" />
                    <span>Submit Your Homework</span>
                  </h3>
                  <span className="text-xs text-ink-soft italic">
                    Requires notes or at least 1 attachment
                  </span>
                </div>

                {/* Submission note */}
                <div className="space-y-1">
                  <Textarea
                    label="Submission Notes"
                    value={note}
                    onChange={(e) => setNote(e.target.value)}
                    placeholder="Write a message, answer details, or notes here..."
                    rows={4}
                    disabled={loading || uploading}
                  />
                </div>

                {/* Attachments Section */}
                <div className="space-y-4 border-t border-cream-100 pt-3">
                  <h4 className="text-sm font-bold text-night-900">
                    Attachments
                  </h4>

                  {/* Added Attachments List */}
                  {attachments.length > 0 && (
                    <div className="grid gap-2 sm:grid-cols-2">
                      {attachments.map((att, idx) => (
                        <div
                          key={idx}
                          className="flex items-center justify-between gap-3 rounded-lg border border-cream-200 bg-cream-50/30 p-2.5"
                        >
                          <div className="flex items-center gap-2 overflow-hidden">
                            {att.type === "IMAGE" && (
                              <ImageIcon className="h-4 w-4 shrink-0 text-success" />
                            )}
                            {att.type === "PDF" && (
                              <FileText className="h-4 w-4 shrink-0 text-error" />
                            )}
                            {att.type === "YOUTUBE" && (
                              <LinkIcon className="h-4 w-4 shrink-0 text-studies" />
                            )}
                            {att.type === "LINK" && (
                              <LinkIcon className="h-4 w-4 shrink-0 text-arabic" />
                            )}
                            <span className="truncate text-xs font-medium text-night-900">
                              {att.fileName}
                            </span>
                          </div>
                          <button
                            type="button"
                            onClick={() => handleRemoveAttachment(idx)}
                            className="p-1 text-ink-soft transition-colors hover:text-error"
                          >
                            <Trash2 className="h-4 w-4" />
                          </button>
                        </div>
                      ))}
                    </div>
                  )}

                  {/* Add Attachment Panel */}
                  <div className="space-y-3 rounded-lg border border-cream-200 bg-cream-50/50 p-4">
                    <div className="grid gap-3 sm:grid-cols-3">
                      <div>
                        <label className="text-xs font-bold tracking-wider text-ink-soft uppercase">
                          Type
                        </label>
                        <Select
                          value={attType}
                          onChange={(e) => {
                            setAttType(e.target.value as any);
                            setAttUrl("");
                            setAttName("");
                            setAttError(null);
                          }}
                          disabled={loading || uploading}
                        >
                          <option value="IMAGE">Image File</option>
                          <option value="PDF">PDF File</option>
                          <option value="YOUTUBE">YouTube Video</option>
                          <option value="LINK">Web Link</option>
                        </Select>
                      </div>

                      {/* URL input for YouTube/Links, File name for Files */}
                      {attType === "IMAGE" || attType === "PDF" ? (
                        <div className="sm:col-span-2">
                          <label className="text-xs font-bold tracking-wider text-ink-soft uppercase">
                            File Name
                          </label>
                          <Input
                            placeholder="e.g. homework-page-1"
                            value={attName}
                            onChange={(e) => setAttName(e.target.value)}
                            disabled={loading || uploading}
                          />
                        </div>
                      ) : (
                        <div className="sm:col-span-2">
                          <label className="text-xs font-bold tracking-wider text-ink-soft uppercase">
                            {attType === "YOUTUBE"
                              ? "YouTube Video URL"
                              : "Web URL"}
                          </label>
                          <Input
                            placeholder={
                              attType === "YOUTUBE"
                                ? "e.g. https://www.youtube.com/watch?v=..."
                                : "e.g. https://my-blog-resource.com"
                            }
                            value={attUrl}
                            onChange={(e) => setAttUrl(e.target.value)}
                            disabled={loading || uploading}
                          />
                        </div>
                      )}
                    </div>

                    {attError && (
                      <p className="text-xs text-error">{attError}</p>
                    )}

                    {/* Progress Bar for Mock Uploading */}
                    {uploading && (
                      <div className="space-y-1">
                        <div className="flex justify-between text-xs font-semibold text-ink-soft">
                          <span>Uploading...</span>
                          <span>{uploadProgress}%</span>
                        </div>
                        <div className="h-1.5 w-full overflow-hidden rounded-full bg-cream-200">
                          <div
                            className="h-1.5 rounded-full bg-gold-500 transition-all"
                            style={{ width: `${uploadProgress}%` }}
                          />
                        </div>
                      </div>
                    )}

                    <Button
                      type="button"
                      variant="ghost"
                      onClick={handleAddAttachment}
                      disabled={loading || uploading}
                      className="flex items-center gap-1.5"
                    >
                      <Plus className="h-4 w-4" />
                      <span>
                        {attType === "IMAGE" || attType === "PDF"
                          ? "Upload File"
                          : "Add Link"}
                      </span>
                    </Button>
                  </div>
                </div>

                <div className="flex justify-end pt-3">
                  <Button
                    type="submit"
                    loading={loading}
                    disabled={uploading}
                    className="px-8"
                  >
                    Submit Homework
                  </Button>
                </div>
              </Card>
            </form>
          ) : (
            /* ==================== STATE 2: LOCKED PAST DUE ==================== */
            <Card className="flex items-start gap-4 border border-error/20 bg-error/5 p-6 shadow-soft">
              <AlertTriangle className="mt-0.5 h-6 w-6 shrink-0 text-error" />
              <div className="space-y-1">
                <h3 className="font-bold text-error">Submissions Locked</h3>
                <p className="text-sm leading-relaxed text-ink">
                  {submitBlockedReason ||
                    `This homework is past the due date (${formattedDueDate}) and late submissions are disabled by your teacher. You can no longer submit work for this assignment.`}
                </p>
              </div>
            </Card>
          )}
        </div>

        {/* Right column: Feedback panel / status */}
        <div className="space-y-6">
          <Card className="space-y-4 border border-cream-200 bg-night-900 p-6 text-cream-50 shadow-soft">
            <h3 className="flex items-center gap-2 border-b border-night-800 pb-3 text-lg font-bold">
              <Award className="h-5 w-5 text-gold-500" />
              <span>Assessment Summary</span>
            </h3>

            {submission && submission.status === "GRADED" ? (
              <div className="space-y-5">
                <div className="space-y-1 rounded-lg border border-night-700 bg-night-800 p-4 text-center">
                  <span className="block text-xs tracking-wider text-cream-100/60 uppercase">
                    Graded Result
                  </span>
                  {homework?.maxScore !== null &&
                  homework?.maxScore !== undefined ? (
                    <div className="flex items-baseline justify-center gap-1.5">
                      <span className="text-4xl font-extrabold text-success">
                        {submission.score}
                      </span>
                      <span className="text-sm text-cream-100/50">
                        / {homework.maxScore}
                      </span>
                    </div>
                  ) : (
                    <div className="flex items-center justify-center gap-2 text-lg font-bold text-success">
                      <CheckCircle2 className="h-6 w-6" /> Completed
                    </div>
                  )}
                  <span className="mt-2 block text-[10px] text-cream-100/40">
                    Graded on{" "}
                    {new Date(submission.gradedAt!).toLocaleDateString(
                      "en-US",
                      { dateStyle: "medium" },
                    )}
                  </span>
                </div>

                {submission.feedback && (
                  <div className="space-y-1.5">
                    <h4 className="text-xs font-bold tracking-wider text-cream-100/60 uppercase">
                      Teacher's Feedback
                    </h4>
                    <p className="rounded-lg border border-night-700 bg-night-800 p-3.5 text-sm leading-relaxed whitespace-pre-wrap text-cream-50">
                      {submission.feedback}
                    </p>
                  </div>
                )}
              </div>
            ) : submission ? (
              <div className="space-y-4 py-6 text-center text-cream-100/70">
                <Clock className="mx-auto h-10 w-10 animate-pulse text-warn" />
                <div>
                  <p className="text-base font-bold text-white">
                    Awaiting Grading
                  </p>
                  <p className="mt-1 text-xs">
                    Your homework has been submitted. Your teacher will grade it
                    soon.
                  </p>
                </div>
              </div>
            ) : (
              <div className="space-y-4 py-6 text-center text-cream-100/50">
                <AlertTriangle className="mx-auto h-10 w-10 text-gold-500" />
                <div>
                  <p className="text-base font-bold text-white">
                    Not Submitted
                  </p>
                  <p className="mt-1 text-xs">
                    Submit your work using the form on the left to receive
                    feedback.
                  </p>
                </div>
              </div>
            )}
          </Card>
        </div>
      </div>
    </div>
  );
}

