"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { type Batch, type Lesson, type Student } from "@/types/shared/homework";
import { Button, Card, Input, Textarea, Select } from "@/components/ui";
import { createHomework, getBatchStudents } from "@/actions/homework";
import { toast } from "sonner";
import { ArrowLeft, Check, Sparkles, Loader2 } from "lucide-react";
import Link from "next/link";
import { useEffect } from "react";

interface CreateHomeworkFormProps {
  batches: Batch[];
  lessons: Lesson[];
  students?: Student[];
}

export function CreateHomeworkForm({
  batches,
  lessons,
  students: initialStudents = [],
}: CreateHomeworkFormProps) {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [loadingStudents, setLoadingStudents] = useState(false);
  const [students, setStudents] = useState<Student[]>(initialStudents);

  // Form states
  const [title, setTitle] = useState("");
  const [instruction, setInstruction] = useState("");
  const [batchId, setBatchId] = useState("");
  const [lessonId, setLessonId] = useState("");
  const [assignedDate, setAssignedDate] = useState(
    () => new Date().toISOString().split("T")[0],
  );
  const [dueDate, setDueDate] = useState("");
  const [status, setStatus] = useState<"DRAFT" | "PUBLISHED">("PUBLISHED");
  const [gradingType, setGradingType] = useState<"graded" | "completion">(
    "graded",
  );
  const [maxScore, setMaxScore] = useState<string>("10");
  const [allowLateSubmission, setAllowLateSubmission] = useState(true);
  const [targetType, setTargetType] = useState<"BATCH" | "SPECIFIC">("BATCH");
  const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);

  // Validation state
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Dynamic student loading on batch change
  useEffect(() => {
    if (!batchId) {
      setStudents([]);
      setSelectedStudentIds([]);
      return;
    }

    const fetchStudents = async () => {
      setLoadingStudents(true);
      const res = await getBatchStudents(batchId);
      setLoadingStudents(false);
      if (res.ok) {
        setStudents(res.data);
        // Initially leave all students unselected so teacher selects them manually
        setSelectedStudentIds([]);
      } else {
        toast.error("Failed to load students for this batch");
      }
    };

    fetchStudents();
  }, [batchId]);

  const handleStudentToggle = (studentId: string) => {
    setSelectedStudentIds((prev) =>
      prev.includes(studentId)
        ? prev.filter((id) => id !== studentId)
        : [...prev, studentId],
    );
  };

  const validate = () => {
    const newErrors: Record<string, string> = {};

    if (!title.trim()) newErrors.title = "Title cannot be empty";
    else if (title.length > 200)
      newErrors.title = "Title cannot exceed 200 characters";

    if (!instruction.trim())
      newErrors.instruction = "Instructions cannot be empty";
    else if (instruction.length > 5000)
      newErrors.instruction = "Instructions cannot exceed 5000 characters";

    if (!batchId) newErrors.batchId = "Please select a batch";

    if (!dueDate) newErrors.dueDate = "Please select a due date";
    else if (dueDate < assignedDate) {
      newErrors.dueDate = "Due date must be on or after the assigned date";
    }

    if (gradingType === "graded") {
      const parsedMax = Number(maxScore);
      if (!maxScore || isNaN(parsedMax) || parsedMax <= 0) {
        newErrors.maxScore = "Max score must be a positive number";
      }
    }

    if (selectedStudentIds.length === 0) {
      newErrors.students = "Please select at least one student";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) {
      toast.error("Please resolve the validation errors");
      return;
    }

    setLoading(true);
    const isAllSelected = selectedStudentIds.length === students.length;
    const finalTargetType = isAllSelected ? "BATCH" : "SPECIFIC";
    const finalStudentIds = isAllSelected ? null : selectedStudentIds;

    const result = await createHomework({
      title,
      instruction,
      batchId,
      lessonId: lessonId || null,
      assignedDate,
      dueDate,
      status,
      maxScore: gradingType === "graded" ? Number(maxScore) : null,
      allowLateSubmission,
      targetType: finalTargetType,
      studentIds: finalStudentIds,
    });

    setLoading(false);

    if (result.ok) {
      toast.success(result.message || "Homework created successfully!");
      router.push("/dashboard/teacher/homework");
      router.refresh();
    } else {
      if (
        (result as any).errorSource &&
        (result as any).errorSource.length > 0
      ) {
        const fieldErrors: Record<string, string> = {};
        (result as any).errorSource.forEach((err: any) => {
          fieldErrors[err.path] = err.message;
        });
        setErrors(fieldErrors);
        toast.error("Please resolve the validation errors");
      } else {
        toast.error(result.error);
      }
    }
  };

  return (
    <form onSubmit={handleSubmit} className="mx-auto max-w-3xl space-y-6">
      <div className="flex items-center gap-3">
        <Link
          href="/dashboard/teacher/homework"
          className="mb-3 inline-flex items-center gap-1 text-sm text-ink-soft transition-colors hover:text-night-900"
        >
          <ArrowLeft className="h-4 w-4" />
          <span>Back</span>
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-night-900">
            Create New Homework
          </h1>
          <p className="text-sm text-ink-soft">
            Publish a new assignment for your students.
          </p>
        </div>
      </div>

      <Card className="space-y-5 border border-cream-200 p-6 shadow-soft">
        <div className="flex w-fit items-center gap-2 rounded-md bg-quran-soft/30 px-3 py-1.5 text-sm font-bold text-quran">
          <Sparkles className="h-4 w-4" />
          <span>Basic Details</span>
        </div>

        {/* Title */}
        <div className="space-y-1">
          <label className="text-sm font-semibold text-night-900">
            Homework Title *
          </label>
          <Input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="e.g. Surah Al-Fatiha — memorise and write"
            disabled={loading}
          />
          {errors.title && <p className="text-xs text-error">{errors.title}</p>}
        </div>

        {/* Instructions */}
        <div className="space-y-1">
          <Textarea
            label="Instructions *"
            value={instruction}
            onChange={(e) => setInstruction(e.target.value)}
            placeholder="Write clear instructions for students..."
            rows={5}
            disabled={loading}
            error={errors.instruction}
          />
          <p className="text-right text-xs text-ink-soft/60">
            {instruction.length}/5000 chars
          </p>
        </div>

        {/* Batch and Lesson */}
        <div className="grid gap-4 sm:grid-cols-2">
          <div className="space-y-1">
            <label className="text-sm font-semibold text-night-900">
              Batch *
            </label>
            <Select
              value={batchId}
              onChange={(e) => setBatchId(e.target.value)}
              disabled={loading}
            >
              <option value="">Select a batch</option>
              {batches.map((b) => (
                <option key={b.id} value={b.id}>
                  {b.name}
                </option>
              ))}
            </Select>
            {errors.batchId && (
              <p className="text-xs text-error">{errors.batchId}</p>
            )}
          </div>

          <div className="space-y-1">
            <label className="text-sm font-semibold text-night-900">
              Link Lesson (Optional)
            </label>
            <Select
              value={lessonId}
              onChange={(e) => setLessonId(e.target.value)}
              disabled={loading}
            >
              <option value="">None</option>
              {lessons.map((l) => (
                <option key={l.id} value={l.id}>
                  {l.title}
                </option>
              ))}
            </Select>
          </div>
        </div>
      </Card>

      {batchId && (
        <>
          <Card className="space-y-5 border border-cream-200 p-6 shadow-soft">
            <div className="flex w-fit items-center gap-2 rounded-md bg-studies-soft/30 px-3 py-1.5 text-sm font-bold text-studies">
              <Sparkles className="h-4 w-4" />
              <span>Grading & Timeline</span>
            </div>

            {/* Dates */}
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-1">
                <label className="text-sm font-semibold text-night-900">
                  Start Date
                </label>
                <Input
                  type="date"
                  value={assignedDate}
                  onChange={(e) => setAssignedDate(e.target.value)}
                  disabled={loading}
                />
              </div>

              <div className="space-y-1">
                <label className="text-sm font-semibold text-night-900">
                  Due Date *
                </label>
                <Input
                  type="date"
                  value={dueDate}
                  onChange={(e) => setDueDate(e.target.value)}
                  disabled={loading}
                />
                {errors.dueDate && (
                  <p className="text-xs text-error">{errors.dueDate}</p>
                )}
              </div>
            </div>

            {/* Grading settings */}
            <div className="grid items-end gap-4 sm:grid-cols-2">
              <div className="space-y-1">
                <label className="text-sm font-semibold text-night-900">
                  Grading Option
                </label>
                <Select
                  value={gradingType}
                  onChange={(e) => setGradingType(e.target.value as any)}
                  disabled={loading}
                >
                  <option value="graded">Score Grading</option>
                  <option value="completion">Completion Only (Ungraded)</option>
                </Select>
              </div>

              {gradingType === "graded" && (
                <div className="space-y-1">
                  <label className="text-sm font-semibold text-night-900">
                    Maximum Score
                  </label>
                  <Input
                    type="number"
                    min="1"
                    value={maxScore}
                    onChange={(e) => setMaxScore(e.target.value)}
                    disabled={loading}
                  />
                  {errors.maxScore && (
                    <p className="text-xs text-error">{errors.maxScore}</p>
                  )}
                </div>
              )}
            </div>

            {/* Allow late submission */}
            <div className="flex items-center gap-3 rounded-lg border border-cream-200/50 bg-cream-50/50 p-3">
              <input
                type="checkbox"
                id="allowLate"
                checked={allowLateSubmission}
                onChange={(e) => setAllowLateSubmission(e.target.checked)}
                className="border-cream-300 h-4.5 w-4.5 rounded text-gold-500 accent-gold-500"
                disabled={loading}
              />
              <label
                htmlFor="allowLate"
                className="text-sm font-medium text-night-900 select-none"
              >
                Allow Late Submissions
                <span className="block text-xs font-normal text-ink-soft">
                  When checked, students can submit homework after the due date,
                  marked as "Submitted late".
                </span>
              </label>
            </div>
          </Card>

          <Card className="space-y-5 border border-cream-200 p-6 shadow-soft">
            <div className="flex w-fit items-center gap-2 rounded-md bg-arabic-soft/30 px-3 py-1.5 text-sm font-bold text-arabic">
              <Sparkles className="h-4 w-4" />
              <span>Audience & Publishing</span>
            </div>

            {/* Student list */}
            <div className="space-y-2">
              <div className="mb-1 flex items-center justify-between gap-4">
                <label className="text-sm font-semibold text-night-900">
                  Assign to Students *
                </label>
                {students.length > 0 && (
                  <button
                    type="button"
                    onClick={() => {
                      if (selectedStudentIds.length === students.length) {
                        setSelectedStudentIds([]);
                      } else {
                        setSelectedStudentIds(students.map((s) => s.id));
                      }
                    }}
                    className="hover:text-gold-700 text-xs font-semibold text-gold-600 transition-colors"
                  >
                    {selectedStudentIds.length === students.length
                      ? "Deselect All"
                      : "Select All"}
                  </button>
                )}
              </div>
              <div className="grid max-h-60 min-h-[100px] items-center justify-center gap-2 overflow-y-auto rounded-lg border border-cream-200 bg-cream-50/20 p-3 sm:grid-cols-2">
                {loadingStudents ? (
                  <div className="col-span-2 flex flex-col items-center justify-center gap-2 py-4">
                    <Loader2 className="h-5 w-5 animate-spin text-gold-500" />
                    <p className="text-xs text-ink-soft">Loading students...</p>
                  </div>
                ) : students.length === 0 ? (
                  <div className="col-span-2 py-4 text-center text-xs text-ink-soft">
                    No students found in this batch
                  </div>
                ) : (
                  students.map((student) => {
                    const isSelected = selectedStudentIds.includes(student.id);
                    return (
                      <div
                        key={student.id}
                        onClick={() =>
                          !loading && handleStudentToggle(student.id)
                        }
                        className={`flex cursor-pointer items-center justify-between rounded-md border p-2.5 transition-all select-none ${
                          isSelected
                            ? "border-gold-500/40 bg-gold-500/10 text-night-900"
                            : "hover:border-cream-300 border-cream-200 bg-white text-night-900 hover:bg-cream-50/50"
                        }`}
                      >
                        <div>
                          <p className="text-sm font-semibold">
                            {student.name}
                          </p>
                          <p className="text-xs text-ink-soft">
                            {student.studentCode}
                          </p>
                        </div>
                        {isSelected ? (
                          <div className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-gold-500 p-0.5 text-white shadow-sm">
                            <Check className="h-3.5 w-3.5 stroke-[3]" />
                          </div>
                        ) : (
                          <div className="border-cream-300 h-5 w-5 shrink-0 rounded-full border-2 bg-white transition-colors" />
                        )}
                      </div>
                    );
                  })
                )}
              </div>
              {(errors.students || errors.studentIds) && (
                <p className="text-xs text-error">
                  {errors.students || errors.studentIds}
                </p>
              )}
            </div>

            {/* Publish status */}
            <div className="space-y-1">
              <label className="text-sm font-semibold text-night-900">
                Status
              </label>
              <Select
                value={status}
                onChange={(e) => setStatus(e.target.value as any)}
                disabled={loading}
              >
                <option value="PUBLISHED">
                  Published (Visible to students immediately)
                </option>
                <option value="DRAFT">Draft (Only visible to you)</option>
              </Select>
            </div>
          </Card>

          <div className="flex items-center justify-end gap-3 pt-4">
            <Link
              href="/dashboard/teacher/homework"
              className="inline-flex min-h-[44px] items-center justify-center gap-2 rounded-full border border-cream-200 bg-transparent px-6 font-display text-[15px] font-semibold text-night-900 transition-all duration-150 hover:scale-[1.02] hover:bg-cream-50 active:scale-95"
            >
              Cancel
            </Link>
            <Button type="submit" loading={loading} className="px-8">
              Save Assignment
            </Button>
          </div>
        </>
      )}
    </form>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { type Homework, type Batch, type Lesson, type Student } from "@/types/shared/homework";
import { Button, Card, Input, Textarea, Select } from "@/components/ui";
import {
  updateHomework,
  deleteHomework,
  getBatchStudents,
} from "@/actions/homework";
import { toast } from "sonner";
import {
  ArrowLeft,
  Check,
  Sparkles,
  Trash2,
  AlertTriangle,
  Loader2,
} from "lucide-react";
import Link from "next/link";
import { useEffect } from "react";

interface EditHomeworkFormProps {
  homework: Homework & { studentIds?: string[] };
  batches: Batch[];
  lessons: Lesson[];
  students?: Student[];
  submissionCount: number;
}

export function EditHomeworkForm({
  homework,
  batches,
  lessons,
  students: initialStudents = [],
  submissionCount,
}: EditHomeworkFormProps) {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [loadingStudents, setLoadingStudents] = useState(false);
  const [students, setStudents] = useState<Student[]>(initialStudents);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  const hasSubmissions = submissionCount > 0;

  // Form states
  const [title, setTitle] = useState(homework.title);
  const [instruction, setInstruction] = useState(homework.instruction);
  const [batchId, setBatchId] = useState(homework.batch.id);
  const [lessonId, setLessonId] = useState(homework.lesson?.id || "");
  const [assignedDate, setAssignedDate] = useState(homework.assignedDate);
  const [dueDate, setDueDate] = useState(homework.dueDate);
  const [status, setStatus] = useState<"DRAFT" | "PUBLISHED">(homework.status);
  const [gradingType, setGradingType] = useState<"graded" | "completion">(
    homework.maxScore !== null ? "graded" : "completion",
  );
  const [maxScore, setMaxScore] = useState<string>(
    homework.maxScore?.toString() || "10",
  );
  const [allowLateSubmission, setAllowLateSubmission] = useState(
    homework.allowLateSubmission,
  );
  const [targetType, setTargetType] = useState<"BATCH" | "SPECIFIC">(
    homework.targetType,
  );
  const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>(
    homework.studentIds || [],
  );

  // Validation state
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Dynamic student loading on batch change
  useEffect(() => {
    if (hasSubmissions || !batchId) return;

    const fetchStudents = async () => {
      setLoadingStudents(true);
      const res = await getBatchStudents(batchId);
      setLoadingStudents(false);
      if (res.ok) {
        setStudents(res.data);
        // If this is the batch from the original homework and it was targetType BATCH, select all.
        // If they change the batch, select all new students by default.
        if (batchId === homework.batch.id && homework.targetType === "BATCH") {
          setSelectedStudentIds(res.data.map((s) => s.id));
        } else if (batchId !== homework.batch.id) {
          setSelectedStudentIds(res.data.map((s) => s.id));
        }
      } else {
        toast.error("Failed to load students for this batch");
      }
    };

    fetchStudents();
  }, [batchId, hasSubmissions, homework.batch.id, homework.targetType]);

  const handleStudentToggle = (studentId: string) => {
    if (hasSubmissions) return; // Cannot edit target audience
    setSelectedStudentIds((prev) =>
      prev.includes(studentId)
        ? prev.filter((id) => id !== studentId)
        : [...prev, studentId],
    );
  };

  const validate = () => {
    const newErrors: Record<string, string> = {};

    if (!title.trim()) newErrors.title = "Title cannot be empty";
    else if (title.length > 200)
      newErrors.title = "Title cannot exceed 200 characters";

    if (!instruction.trim())
      newErrors.instruction = "Instructions cannot be empty";
    else if (instruction.length > 5000)
      newErrors.instruction = "Instructions cannot exceed 5000 characters";

    if (!dueDate) newErrors.dueDate = "Please select a due date";
    else if (dueDate < assignedDate) {
      newErrors.dueDate = "Due date must be on or after the assigned date";
    }

    if (gradingType === "graded") {
      const parsedMax = Number(maxScore);
      if (!maxScore || isNaN(parsedMax) || parsedMax <= 0) {
        newErrors.maxScore = "Max score must be a positive number";
      }
    }

    if (selectedStudentIds.length === 0) {
      newErrors.students = "Please select at least one student";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) {
      toast.error("Please resolve the validation errors");
      return;
    }

    setLoading(true);
    const isAllSelected = selectedStudentIds.length === students.length;
    const finalTargetType = isAllSelected ? "BATCH" : "SPECIFIC";
    const finalStudentIds = isAllSelected ? null : selectedStudentIds;

    const result = await updateHomework(homework.id, {
      title,
      instruction,
      batchId: hasSubmissions ? undefined : batchId,
      lessonId: lessonId || null,
      assignedDate,
      dueDate,
      status,
      maxScore: gradingType === "graded" ? Number(maxScore) : null,
      allowLateSubmission,
      targetType: hasSubmissions ? undefined : finalTargetType,
      studentIds: hasSubmissions ? undefined : finalStudentIds,
    });

    setLoading(false);

    if (result.ok) {
      toast.success(result.message || "Homework updated successfully!");
      router.push("/dashboard/teacher/homework");
      router.refresh();
    } else {
      if (
        (result as any).errorSource &&
        (result as any).errorSource.length > 0
      ) {
        const fieldErrors: Record<string, string> = {};
        (result as any).errorSource.forEach((err: any) => {
          fieldErrors[err.path] = err.message;
        });
        setErrors(fieldErrors);
        toast.error("Please resolve the validation errors");
      } else {
        toast.error(result.error);
      }
    }
  };

  const handleDelete = async () => {
    setLoading(true);
    const result = await deleteHomework(homework.id);
    setLoading(false);

    if (result.ok) {
      toast.success(result.message || "Homework deleted successfully!");
      router.push("/dashboard/teacher/homework");
      router.refresh();
    } else {
      toast.error(result.error);
    }
  };

  return (
    <div className="mx-auto max-w-3xl space-y-6">
      <div className="flex items-center gap-3">
        <Link
          href="/dashboard/teacher/homework"
          className="mb-3 inline-flex items-center gap-1 text-sm text-ink-soft transition-colors hover:text-night-900"
        >
          <ArrowLeft className="h-4 w-4" />
          <span>Back</span>
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-night-900">Edit Homework</h1>
          <p className="text-sm text-ink-soft">
            Update your homework assignment details or delete it.
          </p>
        </div>
      </div>

      {hasSubmissions && (
        <div className="flex gap-3 rounded-lg border border-warn/20 bg-warn/10 p-4 text-sm text-night-900">
          <AlertTriangle className="h-5 w-5 shrink-0 text-warn" />
          <div>
            <p className="font-semibold text-warn">Target Controls Locked</p>
            <p className="mt-0.5 text-xs text-ink-soft">
              Some configurations (Batch, Target Audience, and Student List)
              cannot be edited because students have already submitted their
              homework.
            </p>
          </div>
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-6">
        <Card className="space-y-5 border border-cream-200 p-6 shadow-soft">
          <div className="flex w-fit items-center gap-2 rounded-md bg-quran-soft/30 px-3 py-1.5 text-sm font-bold text-quran">
            <Sparkles className="h-4 w-4" />
            <span>Basic Details</span>
          </div>

          {/* Title */}
          <div className="space-y-1">
            <label className="text-sm font-semibold text-night-900">
              Homework Title *
            </label>
            <Input
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="e.g. Surah Al-Fatiha"
              disabled={loading}
            />
            {errors.title && (
              <p className="text-xs text-error">{errors.title}</p>
            )}
          </div>

          {/* Instructions */}
          <div className="space-y-1">
            <Textarea
              label="Instructions *"
              value={instruction}
              onChange={(e) => setInstruction(e.target.value)}
              placeholder="Write clear instructions for students..."
              rows={5}
              disabled={loading}
              error={errors.instruction}
            />
            <p className="text-right text-xs text-ink-soft/60">
              {instruction.length}/5000 chars
            </p>
          </div>

          {/* Batch and Lesson */}
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-1">
              <label className="text-sm font-semibold text-night-900">
                Batch *
              </label>
              <Select
                value={batchId}
                onChange={(e) => setBatchId(e.target.value)}
                disabled={loading || hasSubmissions}
              >
                {batches.map((b) => (
                  <option key={b.id} value={b.id}>
                    {b.name}
                  </option>
                ))}
              </Select>
            </div>

            <div className="space-y-1">
              <label className="text-sm font-semibold text-night-900">
                Link Lesson (Optional)
              </label>
              <Select
                value={lessonId}
                onChange={(e) => setLessonId(e.target.value)}
                disabled={loading}
              >
                <option value="">None</option>
                {lessons.map((l) => (
                  <option key={l.id} value={l.id}>
                    {l.title}
                  </option>
                ))}
              </Select>
            </div>
          </div>
        </Card>

        <Card className="space-y-5 border border-cream-200 p-6 shadow-soft">
          <div className="flex w-fit items-center gap-2 rounded-md bg-studies-soft/30 px-3 py-1.5 text-sm font-bold text-studies">
            <Sparkles className="h-4 w-4" />
            <span>Grading & Timeline</span>
          </div>

          {/* Dates */}
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-1">
              <label className="text-sm font-semibold text-night-900">
                Start Date
              </label>
              <Input
                type="date"
                value={assignedDate}
                onChange={(e) => setAssignedDate(e.target.value)}
                disabled={loading}
              />
            </div>

            <div className="space-y-1">
              <label className="text-sm font-semibold text-night-900">
                Due Date *
              </label>
              <Input
                type="date"
                value={dueDate}
                onChange={(e) => setDueDate(e.target.value)}
                disabled={loading}
              />
              {errors.dueDate && (
                <p className="text-xs text-error">{errors.dueDate}</p>
              )}
            </div>
          </div>

          {/* Grading settings */}
          <div className="grid items-end gap-4 sm:grid-cols-2">
            <div className="space-y-1">
              <label className="text-sm font-semibold text-night-900">
                Grading Option
              </label>
              <Select
                value={gradingType}
                onChange={(e) => setGradingType(e.target.value as any)}
                disabled={loading}
              >
                <option value="graded">Score Grading</option>
                <option value="completion">Completion Only (Ungraded)</option>
              </Select>
            </div>

            {gradingType === "graded" && (
              <div className="space-y-1">
                <label className="text-sm font-semibold text-night-900">
                  Maximum Score
                </label>
                <Input
                  type="number"
                  min="1"
                  value={maxScore}
                  onChange={(e) => setMaxScore(e.target.value)}
                  disabled={loading}
                />
                {errors.maxScore && (
                  <p className="text-xs text-error">{errors.maxScore}</p>
                )}
              </div>
            )}
          </div>

          {/* Allow late submission */}
          <div className="flex items-center gap-3 rounded-lg border border-cream-200/50 bg-cream-50/50 p-3">
            <input
              type="checkbox"
              id="allowLate"
              checked={allowLateSubmission}
              onChange={(e) => setAllowLateSubmission(e.target.checked)}
              className="border-cream-300 h-4.5 w-4.5 rounded text-gold-500 accent-gold-500"
              disabled={loading}
            />
            <label
              htmlFor="allowLate"
              className="text-sm font-medium text-night-900 select-none"
            >
              Allow Late Submissions
              <span className="block text-xs font-normal text-ink-soft">
                When checked, students can submit homework after the due date,
                marked as "Submitted late".
              </span>
            </label>
          </div>
        </Card>

        <Card className="space-y-5 border border-cream-200 p-6 shadow-soft">
          <div className="flex w-fit items-center gap-2 rounded-md bg-arabic-soft/30 px-3 py-1.5 text-sm font-bold text-arabic">
            <Sparkles className="h-4 w-4" />
            <span>Audience & Publishing</span>
          </div>

          {/* Student list */}
          <div className="space-y-2">
            <div className="mb-1 flex items-center justify-between gap-4">
              <label className="text-sm font-semibold text-night-900">
                Assign to Students *
              </label>
              {students.length > 0 && !hasSubmissions && (
                <button
                  type="button"
                  onClick={() => {
                    if (selectedStudentIds.length === students.length) {
                      setSelectedStudentIds([]);
                    } else {
                      setSelectedStudentIds(students.map((s) => s.id));
                    }
                  }}
                  className="hover:text-gold-700 text-xs font-semibold text-gold-600 transition-colors"
                >
                  {selectedStudentIds.length === students.length
                    ? "Deselect All"
                    : "Select All"}
                </button>
              )}
            </div>
            <div className="grid max-h-60 min-h-[100px] items-center justify-center gap-2 overflow-y-auto rounded-lg border border-cream-200 bg-cream-50/20 p-3 sm:grid-cols-2">
              {loadingStudents ? (
                <div className="col-span-2 flex flex-col items-center justify-center gap-2 py-4">
                  <Loader2 className="h-5 w-5 animate-spin text-gold-500" />
                  <p className="text-xs text-ink-soft">Loading students...</p>
                </div>
              ) : students.length === 0 ? (
                <div className="col-span-2 py-4 text-center text-xs text-ink-soft">
                  No students found in this batch
                </div>
              ) : (
                students.map((student) => {
                  const isSelected = selectedStudentIds.includes(student.id);
                  return (
                    <div
                      key={student.id}
                      onClick={() =>
                        !hasSubmissions && handleStudentToggle(student.id)
                      }
                      className={`flex cursor-pointer items-center justify-between rounded-md border p-2.5 transition-all select-none ${
                        isSelected
                          ? "border-gold-500/40 bg-gold-500/10 text-night-900"
                          : "hover:border-cream-300 border-cream-200 bg-white text-night-900 hover:bg-cream-50/50"
                      } ${hasSubmissions ? "pointer-events-none opacity-80" : ""}`}
                    >
                      <div>
                        <p className="text-sm font-semibold">{student.name}</p>
                        <p className="text-xs text-ink-soft">
                          {student.studentCode}
                        </p>
                      </div>
                      {isSelected ? (
                        <div className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-gold-500 p-0.5 text-white shadow-sm">
                          <Check className="h-3.5 w-3.5 stroke-[3]" />
                        </div>
                      ) : (
                        <div className="border-cream-300 h-5 w-5 shrink-0 rounded-full border-2 bg-white transition-colors" />
                      )}
                    </div>
                  );
                })
              )}
            </div>
            {(errors.students || errors.studentIds) && (
              <p className="text-xs text-error">
                {errors.students || errors.studentIds}
              </p>
            )}
          </div>

          {/* Publish status */}
          <div className="space-y-1">
            <label className="text-sm font-semibold text-night-900">
              Status
            </label>
            <Select
              value={status}
              onChange={(e) => setStatus(e.target.value as any)}
              disabled={loading}
            >
              <option value="PUBLISHED">Published (Visible to students)</option>
              <option value="DRAFT">Draft (Only visible to you)</option>
            </Select>
          </div>
        </Card>

        {/* Action Buttons */}
        <div className="flex items-center justify-between pt-4">
          <Button
            type="button"
            variant="danger"
            onClick={() => setShowDeleteConfirm(true)}
            disabled={loading}
            className="flex items-center gap-2"
          >
            <Trash2 className="h-4 w-4" />
            <span>Delete Homework</span>
          </Button>

          <div className="flex items-center gap-3">
            <Link
              href="/dashboard/teacher/homework"
              className="inline-flex min-h-[44px] items-center justify-center gap-2 rounded-full border border-cream-200 bg-transparent px-6 font-display text-[15px] font-semibold text-night-900 transition-all duration-150 hover:scale-[1.02] hover:bg-cream-50 active:scale-95"
            >
              Cancel
            </Link>
            <Button type="submit" loading={loading} className="px-8">
              Update Assignment
            </Button>
          </div>
        </div>
      </form>

      {/* Delete Confirmation Modal */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-night-900/50 p-4 backdrop-blur-sm">
          <Card className="w-full max-w-md space-y-4 border border-cream-200 p-6 shadow-lift">
            <div className="flex items-center gap-3 text-error">
              <AlertTriangle className="h-6 w-6 shrink-0" />
              <h3 className="text-lg font-bold">Confirm Deletion</h3>
            </div>
            <p className="text-sm text-ink">
              Are you sure you want to delete this homework? This is a permanent
              action.
            </p>
            <div className="rounded bg-error/10 p-3 text-xs font-semibold text-error">
              ⚠️ WARNING: Deleting this homework will permanently lose{" "}
              {submissionCount} student submission
              {submissionCount !== 1 ? "s" : ""}.
            </div>
            <div className="flex justify-end gap-3 pt-2">
              <Button
                variant="ghost"
                onClick={() => setShowDeleteConfirm(false)}
                disabled={loading}
              >
                Cancel
              </Button>
              <Button variant="danger" onClick={handleDelete} loading={loading}>
                Delete Permanently
              </Button>
            </div>
          </Card>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { type SubmissionDetails } from "@/types/shared/homework";
import { Button, Card, Input, Textarea } from "@/components/ui";
import { gradeSubmission } from "@/actions/homework";
import { toast } from "sonner";
import { YouTubeEmbed } from "@/components/shared/homework/YouTubeEmbed";
import {
  ArrowLeft,
  ExternalLink,
  FileText,
  Image as ImageIcon,
  Link as LinkIcon,
  AlertCircle,
  Calendar,
  CheckSquare,
} from "lucide-react";
import Link from "next/link";
import { formatCalendarDate } from "@/lib/utils/date";

interface GradingFormProps {
  submission: SubmissionDetails;
  homeworkId: string;
}

export function GradingForm({ submission, homeworkId }: GradingFormProps) {
  const router = useRouter();
  const [loading, setLoading] = useState(false);

  const hw = submission?.homework;
  const isCompletionOnly = hw?.maxScore === null;

  // Grade state
  const [score, setScore] = useState<string>(
    submission?.score !== null && submission?.score !== undefined
      ? submission.score.toString()
      : "",
  );
  const [isCompleted, setIsCompleted] = useState<boolean>(
    submission?.score === 1, // Complete is stored as 1, Incomplete as 0
  );
  const [feedback, setFeedback] = useState<string>(submission?.feedback || "");
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    // Validation
    let parsedScore: number | null = null;
    if (!isCompletionOnly) {
      parsedScore = Number(score);
      if (
        score === "" ||
        isNaN(parsedScore) ||
        parsedScore < 0 ||
        parsedScore > (hw?.maxScore || 0)
      ) {
        setError(`Score must be a number between 0 and ${hw?.maxScore || 0}`);
        return;
      }
      if (!Number.isInteger(parsedScore)) {
        setError(
          "Score must be a whole number (e.g. 8 or 9). Decimal scores like 8.5 are not allowed.",
        );
        return;
      }
    }

    setLoading(true);
    const result = await gradeSubmission(submission?.id, {
      score: isCompletionOnly ? null : parsedScore,
      feedback: feedback.trim() || null,
      isCompleted: isCompletionOnly ? isCompleted : undefined,
    });
    setLoading(false);

    if (result.ok) {
      toast.success("Submission graded successfully!");
      router.push(`/dashboard/teacher/homework/${homeworkId}/submissions`);
      router.refresh();
    } else {
      const msg = result.error || "Failed to grade submission";
      toast.error(msg);
      setError(msg);
    }
  };

  const formattedSubmitted = submission?.submittedAt
    ? new Date(submission.submittedAt).toLocaleString("en-US", {
        dateStyle: "medium",
        timeStyle: "short",
      })
    : "—";

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-3">
        <Link
          href={`/dashboard/teacher/homework/${homeworkId}/submissions`}
          className="mb-3 inline-flex items-center gap-1 text-sm text-ink-soft transition-colors hover:text-night-900"
        >
          <ArrowLeft className="h-4 w-4" />
          <span>Back</span>
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-night-900">
            Grade Submission
          </h1>
          <p className="text-sm text-ink-soft">
            Reviewing work from{" "}
            <strong className="text-night-900">
              {submission?.student?.name || "Student"}
            </strong>{" "}
            ({submission?.student?.studentCode || ""})
          </p>
        </div>
      </div>

      <div className="grid gap-6 lg:grid-cols-3">
        {/* Left Side: Submission & Instructions */}
        <div className="space-y-6 lg:col-span-2">
          {/* Homework Prompt */}
          <Card className="space-y-2 border border-cream-200 p-6 shadow-soft">
            <div className="flex items-center justify-between text-xs text-ink-soft">
              <span className="rounded bg-quran-soft px-2 py-0.5 font-semibold text-quran">
                Prompt
              </span>
              <span className="flex items-center gap-1">
                <Calendar className="h-3.5 w-3.5" /> Due:{" "}
                {formatCalendarDate(hw?.dueDate)}
              </span>
            </div>
            <h2 className="text-lg font-bold text-night-900">
              {hw?.title || "Homework Details"}
            </h2>
            <div className="rounded-lg border border-cream-200/50 bg-cream-50/50 p-4 text-sm whitespace-pre-wrap text-ink">
              {hw?.instruction || ""}
            </div>
          </Card>

          {/* Student's Submission Note */}
          <Card className="space-y-4 border border-cream-200 p-6 shadow-soft">
            <div className="flex items-center justify-between border-b border-cream-100 pb-3">
              <h3 className="font-bold text-night-900">Student's Notes</h3>
              <span className="text-xs text-ink-soft">
                Submitted: {formattedSubmitted}
              </span>
            </div>
            {submission.note ? (
              <p className="rounded-lg border border-cream-200/50 bg-cream-50/50 p-4 text-sm whitespace-pre-wrap text-ink">
                {submission.note}
              </p>
            ) : (
              <p className="text-sm text-ink-soft italic">
                No text notes provided by student.
              </p>
            )}

            {/* Attachments Section */}
            {submission.attachments.length > 0 && (
              <div className="space-y-4 border-t border-cream-100 pt-4">
                <h4 className="text-sm font-bold text-night-900">
                  Attachments ({submission.attachments.length})
                </h4>
                <div className="grid gap-4 sm:grid-cols-2">
                  {submission.attachments
                    .sort((a, b) => a.order - b.order)
                    .map((att) => {
                      return (
                        <div
                          key={att.id}
                          className="flex flex-col gap-2 rounded-lg border border-cream-200 bg-white p-3 shadow-sm transition-all hover:shadow"
                        >
                          <div className="mb-1 flex items-center justify-between gap-2 border-b border-cream-100 pb-2">
                            <span className="inline-flex items-center gap-1.5 text-xs font-semibold text-ink-soft">
                              {att.type === "IMAGE" && (
                                <ImageIcon className="h-3.5 w-3.5 text-success" />
                              )}
                              {att.type === "PDF" && (
                                <FileText className="h-3.5 w-3.5 text-error" />
                              )}
                              {att.type === "YOUTUBE" && (
                                <LinkIcon className="h-3.5 w-3.5 text-studies" />
                              )}
                              {att.type === "LINK" && (
                                <ExternalLink className="h-3.5 w-3.5 text-arabic" />
                              )}
                              {att.type}
                            </span>
                            <a
                              href={att.url}
                              target="_blank"
                              rel="noreferrer"
                              className="flex items-center gap-1 text-xs font-bold text-quran hover:underline"
                            >
                              Open <ExternalLink className="h-3 w-3" />
                            </a>
                          </div>

                          {att.type === "IMAGE" && (
                            <div className="relative aspect-video w-full overflow-hidden rounded border bg-cream-50">
                              <img
                                src={att.url}
                                alt={att.fileName || "Student work"}
                                className="h-full w-full object-cover"
                              />
                            </div>
                          )}

                          {att.type === "YOUTUBE" && (
                            <YouTubeEmbed url={att.url} className="mt-1" />
                          )}

                          {att.fileName && (
                            <span className="text-xs font-medium break-all text-night-900">
                              {att.fileName}
                            </span>
                          )}
                        </div>
                      );
                    })}
                </div>
              </div>
            )}
          </Card>
        </div>

        {/* Right Side: Grading Control Panel */}
        <div>
          <Card className="sticky top-4 space-y-6 border border-cream-200 bg-night-900 p-6 text-cream-50 shadow-soft">
            <h3 className="border-b border-night-800 pb-3 text-lg font-bold">
              Grading Dashboard
            </h3>

            <form onSubmit={handleSubmit} className="space-y-5">
              {/* Grading Input */}
              {isCompletionOnly ? (
                <div className="flex items-center gap-3 rounded-lg border border-night-700 bg-night-800 p-3">
                  <input
                    type="checkbox"
                    id="isCompleted"
                    checked={isCompleted}
                    onChange={(e) => setIsCompleted(e.target.checked)}
                    className="h-5 w-5 rounded border-night-700 bg-night-900 text-gold-500 accent-gold-500"
                    disabled={loading}
                  />
                  <label
                    htmlFor="isCompleted"
                    className="cursor-pointer text-sm font-semibold select-none"
                  >
                    Mark as Completed
                    <span className="mt-0.5 block text-xs font-normal text-cream-100/60">
                      This homework does not require a grade score.
                    </span>
                  </label>
                </div>
              ) : (
                <div className="space-y-1">
                  <label className="text-sm font-semibold">Grade Score *</label>
                  <div className="flex items-center gap-2">
                    <input
                      type="number"
                      min="0"
                      max={hw.maxScore || 10}
                      step="0.5"
                      value={score}
                      onChange={(e) => setScore(e.target.value)}
                      placeholder="Enter score"
                      className="w-full rounded-md border border-night-700 bg-night-800 px-4 py-2.5 text-cream-50 outline-none focus:border-gold-500"
                      disabled={loading}
                    />
                    <span className="text-lg font-bold text-cream-200">
                      / {hw.maxScore}
                    </span>
                  </div>
                  {error && (
                    <p className="flex items-center gap-1 pt-1 text-xs text-error">
                      <AlertCircle className="h-3 w-3" /> {error}
                    </p>
                  )}
                </div>
              )}

              {/* Feedback Input */}
              <div className="space-y-1">
                <label className="text-sm font-semibold">
                  Teacher Feedback
                </label>
                <textarea
                  value={feedback}
                  onChange={(e) => setFeedback(e.target.value)}
                  placeholder="Provide guidance or feedback for the student..."
                  rows={4}
                  className="w-full rounded-md border border-night-700 bg-night-800 p-3 text-sm text-cream-50 outline-none placeholder:text-cream-100/40 focus:border-gold-500"
                  disabled={loading}
                />
              </div>

              {submission.status === "GRADED" && (
                <div className="rounded bg-night-800/40 p-2 text-[11px] text-cream-100/50">
                  * Submission is already graded. Submitting again will update
                  the record.
                </div>
              )}

              {/* Submit Button */}
              <Button type="submit" loading={loading} block>
                {submission.status === "GRADED"
                  ? "Update Grade"
                  : "Submit Grade"}
              </Button>
            </form>
          </Card>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { type HomeworkSubmissionSummary } from "@/types/shared/homework";
import { Button, Card } from "@/components/ui";
import { StatusChip } from "@/components/shared/homework/StatusChip";
import { bulkGradeSubmissions } from "@/actions/homework";
import { toast } from "sonner";
import { CheckSquare, Square, Check, Loader2, AlertCircle } from "lucide-react";
import Link from "next/link";

interface SubmissionsRosterTableProps {
  homeworkId: string;
  homework: HomeworkSubmissionSummary["homework"];
  results: HomeworkSubmissionSummary["results"];
}

export function SubmissionsRosterTable({
  homeworkId,
  homework,
  results = [],
}: SubmissionsRosterTableProps) {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [isPending, startTransition] = useTransition();

  const isCompletionOnly = homework?.maxScore === null;
  const safeResults = results || [];

  // Filter out students who don't have submissions (cannot be graded)
  const gradableSubmissions = safeResults.filter(
    (r) => r?.submissionId !== null && r?.submissionId !== undefined,
  );

  const handleSelectAll = () => {
    if (selectedIds.length === gradableSubmissions.length) {
      setSelectedIds([]);
    } else {
      setSelectedIds(gradableSubmissions.map((r) => r.submissionId!));
    }
  };

  const handleSelectRow = (submissionId: string) => {
    setSelectedIds((prev) =>
      prev.includes(submissionId)
        ? prev.filter((id) => id !== submissionId)
        : [...prev, submissionId],
    );
  };

  const handleBulkGrade = (isCompleted: boolean) => {
    if (selectedIds.length === 0) return;

    startTransition(async () => {
      const grades = selectedIds.map((id) => ({
        submissionId: id,
        isCompleted,
        feedback: "Graded via bulk action.",
      }));

      const res = await bulkGradeSubmissions(grades);
      if (res.ok) {
        setSelectedIds([]);
        toast.success(res.message || "Bulk grading applied successfully!");
      } else {
        toast.error(res.error || "Failed to apply bulk grading.");
      }
    });
  };

  return (
    <div className="space-y-4">
      {/* Bulk Action Bar (Visible only for completion-only and when selections exist) */}
      {isCompletionOnly && gradableSubmissions.length > 0 && (
        <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-cream-200 bg-cream-50/50 p-4">
          <div className="flex items-center gap-2 text-sm font-medium text-night-900">
            <span>
              Selected{" "}
              <strong className="text-gold-600">{selectedIds.length}</strong> of{" "}
              <strong>{gradableSubmissions.length}</strong> gradable
              submission(s)
            </span>
          </div>

          <div className="flex items-center gap-2">
            <Button
              size="sm"
              variant="night"
              disabled={selectedIds.length === 0 || isPending}
              onClick={() => handleBulkGrade(true)}
              className="flex items-center gap-1.5"
            >
              {isPending ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
              ) : (
                <Check className="h-3.5 w-3.5" />
              )}
              <span>Mark as Completed</span>
            </Button>
            <Button
              size="sm"
              variant="ghost"
              disabled={selectedIds.length === 0 || isPending}
              onClick={() => handleBulkGrade(false)}
              className="border-cream-300 flex items-center gap-1.5 hover:border-gold-500 hover:text-gold-600"
            >
              <span>Mark as Incomplete</span>
            </Button>
          </div>
        </div>
      )}

      {/* Roster Table */}
      <Card className="overflow-hidden border border-cream-200 p-0 shadow-soft">
        <div className="overflow-x-auto">
          <table className="w-full border-collapse text-left">
            <thead>
              <tr className="border-b border-cream-100 bg-cream-50/50 text-xs font-bold tracking-wider text-ink-soft uppercase">
                {isCompletionOnly && (
                  <th className="w-12 px-6 py-3.5">
                    <button
                      type="button"
                      onClick={handleSelectAll}
                      disabled={gradableSubmissions.length === 0}
                      className="text-ink-soft transition-colors hover:text-gold-500 disabled:opacity-40"
                    >
                      {selectedIds.length === gradableSubmissions.length &&
                      gradableSubmissions.length > 0 ? (
                        <CheckSquare className="h-5 w-5 text-gold-500" />
                      ) : (
                        <Square className="h-5 w-5" />
                      )}
                    </button>
                  </th>
                )}
                <th className="px-6 py-3.5">Student</th>
                <th className="px-6 py-3.5">Status</th>
                <th className="px-6 py-3.5">Submitted At</th>
                {!isCompletionOnly && (
                  <th className="px-6 py-3.5 text-center">Score</th>
                )}
                <th className="px-6 py-3.5 text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-cream-100 text-sm text-ink">
              {safeResults.map((row) => {
                const canGrade =
                  (row?.submissionId !== null &&
                    row?.submissionId !== undefined) ||
                  row?.status === "SUBMITTED" ||
                  row?.status === "GRADED";
                const activeSubmissionId =
                  row?.submissionId || row?.assignmentId;
                const isSelected = activeSubmissionId
                  ? selectedIds.includes(activeSubmissionId)
                  : false;

                const formattedDate = row?.submittedAt
                  ? new Date(row.submittedAt).toLocaleString("en-US", {
                      dateStyle: "medium",
                      timeStyle: "short",
                    })
                  : "—";

                return (
                  <tr
                    key={row?.assignmentId || row?.student?.id}
                    className={`transition-all hover:bg-cream-50/30 ${
                      isSelected ? "bg-gold-500/5 hover:bg-gold-500/10" : ""
                    }`}
                  >
                    {isCompletionOnly && (
                      <td className="px-6 py-4">
                        {canGrade ? (
                          <button
                            type="button"
                            onClick={() => handleSelectRow(row.submissionId!)}
                            className="text-ink-soft transition-colors hover:text-gold-500"
                          >
                            {isSelected ? (
                              <CheckSquare className="h-5 w-5 text-gold-500" />
                            ) : (
                              <Square className="h-5 w-5" />
                            )}
                          </button>
                        ) : (
                          <Square className="pointer-events-none h-5 w-5 opacity-20" />
                        )}
                      </td>
                    )}
                    <td className="px-6 py-4">
                      <div className="font-semibold text-night-900">
                        {row?.student?.name || "Student"}
                      </div>
                      <div className="text-xs text-ink-soft">
                        {row?.student?.studentCode || ""}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <StatusChip chip={row?.chip} />
                    </td>
                    <td className="px-6 py-4 text-xs text-ink-soft">
                      {formattedDate}
                    </td>
                    {!isCompletionOnly && (
                      <td className="px-6 py-4 text-center font-display font-semibold">
                        {row?.status === "GRADED" ? (
                          <span className="text-success">
                            {row?.score} / {homework?.maxScore}
                          </span>
                        ) : row?.status === "SUBMITTED" ? (
                          <span className="rounded bg-warn/10 px-2 py-0.5 text-xs text-warn">
                            Awaiting Grade
                          </span>
                        ) : (
                          <span className="text-ink-soft/40">—</span>
                        )}
                      </td>
                    )}
                    <td className="px-6 py-4 text-right">
                      {canGrade ? (
                        <Link
                          href={`/dashboard/teacher/homework/${homeworkId}/submissions/${activeSubmissionId}/grade`}
                          className={
                            row?.status === "GRADED"
                              ? "inline-flex min-h-[38px] items-center justify-center gap-2 rounded-full border border-cream-200 bg-transparent px-4 font-display text-sm font-semibold text-night-900 transition-all duration-150 hover:scale-[1.02] hover:bg-cream-50 active:scale-95"
                              : "inline-flex min-h-[38px] items-center justify-center gap-2 rounded-full bg-gold-500 px-4 font-display text-sm font-semibold text-night-900 shadow-soft transition-all duration-150 hover:scale-[1.02] hover:shadow-[0_0_28px_rgba(245,184,51,0.4)] active:scale-95"
                          }
                        >
                          {row?.status === "GRADED" ? "Edit Grade" : "Grade"}
                        </Link>
                      ) : (
                        <Button
                          size="sm"
                          variant="ghost"
                          disabled
                          className="opacity-40"
                        >
                          Not Submitted
                        </Button>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import {
  CheckCircle2,
  ListChecks,
  Lock,
  Plus,
  Trash2,
  Video,
} from "lucide-react";
import { Button, Card, Input, Select, Textarea } from "@/components/ui";
import { cn } from "@/lib/utils/cn";
import { extractYouTubeId, youTubeThumbnail } from "@/lib/utils/youtube";
import { createLessonAction } from "@/actions/teacher/lesson/create-lesson";
import { updateLessonAction } from "@/actions/teacher/lesson/update-lesson";
import type {
  CreateLessonInput,
  LessonStatus,
  TeacherLessonDetail,
  UpdateLessonInput,
} from "@/types/lesson";

interface LocalOption {
  text: string;
  isCorrect: boolean;
}
interface LocalQuestion {
  key: string;
  text: string;
  options: LocalOption[];
}

interface Props {
  mode: "create" | "edit";
  batches: { id: string; name: string }[];
  lesson?: TeacherLessonDetail;
}

let uid = 0;
const newKey = () => `q_${uid++}`;
const blankQuestion = (): LocalQuestion => ({
  key: newKey(),
  text: "",
  options: [
    { text: "", isCorrect: true },
    { text: "", isCorrect: false },
    { text: "", isCorrect: false },
    { text: "", isCorrect: false },
  ],
});

function todayISO() {
  return new Date().toISOString().slice(0, 10);
}

export function LessonForm({ mode, batches, lesson }: Props) {
  const router = useRouter();
  const isEdit = mode === "edit";

  const initialVideoUrl = lesson?.youtubeVideoId
    ? `https://www.youtube.com/watch?v=${lesson.youtubeVideoId}`
    : "";
  const initialDate = lesson?.date ? lesson.date.slice(0, 10) : todayISO();

  const [batchId, setBatchId] = useState(lesson?.batch?.id ?? "");
  const [title, setTitle] = useState(lesson?.title ?? "");
  const [description, setDescription] = useState(lesson?.description ?? "");
  const [date, setDate] = useState(initialDate);
  const [status, setStatus] = useState<LessonStatus>(lesson?.status ?? "DRAFT");
  const [videoUrl, setVideoUrl] = useState(initialVideoUrl);

  const [quizEnabled, setQuizEnabled] = useState(false);
  const [passMark, setPassMark] = useState<string>("1");
  const [questions, setQuestions] = useState<LocalQuestion[]>([
    blankQuestion(),
  ]);

  const [errors, setErrors] = useState<Record<string, string>>({});
  const [pending, setPending] = useState(false);

  const videoId = useMemo(() => extractYouTubeId(videoUrl), [videoUrl]);
  const videoLooksInvalid = videoUrl.trim().length > 0 && !videoId;

  const updateQuestion = (i: number, patch: Partial<LocalQuestion>) =>
    setQuestions((qs) =>
      qs.map((q, idx) => (idx === i ? { ...q, ...patch } : q)),
    );

  const updateOption = (qi: number, oi: number, text: string) =>
    setQuestions((qs) =>
      qs.map((q, idx) =>
        idx === qi
          ? {
              ...q,
              options: q.options.map((o, j) => (j === oi ? { ...o, text } : o)),
            }
          : q,
      ),
    );

  const setCorrect = (qi: number, oi: number) =>
    setQuestions((qs) =>
      qs.map((q, idx) =>
        idx === qi
          ? {
              ...q,
              options: q.options.map((o, j) => ({ ...o, isCorrect: j === oi })),
            }
          : q,
      ),
    );

  const addQuestion = () => setQuestions((qs) => [...qs, blankQuestion()]);
  const removeQuestion = (i: number) =>
    setQuestions((qs) =>
      qs.length > 1 ? qs.filter((_, idx) => idx !== i) : qs,
    );

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setErrors({});
    if (isEdit) return submitEdit();
    return submitCreate();
  }

  async function submitCreate() {
    const quiz = quizEnabled
      ? {
          passMark: Number(passMark),
          questions: questions.map((q) => ({
            text: q.text.trim(),
            options: q.options.map((o) => ({
              text: o.text.trim(),
              isCorrect: o.isCorrect,
            })),
          })),
        }
      : null;

    const payload: CreateLessonInput = {
      batchId,
      title: title.trim(),
      description: description.trim() || null,
      videoUrl: videoUrl.trim() || undefined,
      date,
      status,
      quiz,
    };

    setPending(true);
    const res = await createLessonAction(payload);
    setPending(false);

    if (!res.success) {
      setErrors(res.fieldErrors ?? {});
      toast.error(res.formError ?? "Could not create lesson.");
      return;
    }
    toast.success(status === "PUBLISHED" ? "Lesson published" : "Draft saved");
    router.push("/dashboard/teacher/lessons");
    router.refresh();
  }

  async function submitEdit() {
    if (!lesson) return;

    const diff: UpdateLessonInput = {};
    if (title.trim() !== (lesson.title ?? "")) diff.title = title.trim();
    if ((description.trim() || null) !== (lesson.description ?? null))
      diff.description = description.trim() || null;
    if (date !== lesson.date.slice(0, 10)) diff.date = date;
    if (status !== lesson.status) diff.status = status;

    const nextVideo = videoUrl.trim();
    if (nextVideo !== initialVideoUrl) diff.videoUrl = nextVideo || null;

    if (Object.keys(diff).length === 0) {
      toast.message("Nothing to update", {
        description: "You haven't changed anything yet.",
      });
      return;
    }

    setPending(true);
    const res = await updateLessonAction(lesson.id, diff);
    setPending(false);

    if (!res.success) {
      setErrors(res.fieldErrors ?? {});
      toast.error(res.formError ?? "Could not update lesson.");
      return;
    }
    toast.success("Lesson updated");
    router.push("/dashboard/teacher/lessons");
    router.refresh();
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-5">
      <Card className="space-y-5">
        <h2 className="font-display text-xl font-bold text-night-900">
          {isEdit ? "Edit lesson" : "New lesson"}
        </h2>

        {isEdit ? (
          <div className="flex flex-col gap-1.5">
            <span className="text-sm font-medium text-night-900">Batch</span>
            <div className="min-h-[44px] rounded-sm border border-cream-200 bg-cream-100 px-4 py-2.5 text-[15px] text-ink-soft">
              {lesson?.batch?.name ?? "—"}
            </div>
            <p className="text-xs text-ink-soft">
              A lesson can't move between batches.
            </p>
          </div>
        ) : (
          <Select
            label="Batch"
            value={batchId}
            onChange={(e) => setBatchId(e.target.value)}
            error={errors.batchId}
          >
            <option value="">Select a batch</option>
            {batches.map((b) => (
              <option key={b.id} value={b.id}>
                {b.name}
              </option>
            ))}
          </Select>
        )}

        <Input
          label="Title"
          placeholder="e.g. Surah Al-Fatihah — Tafsir"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          error={errors.title}
          maxLength={200}
        />

        <Textarea
          label="Description (optional)"
          placeholder="A short summary of what this lesson covers"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          error={errors.description}
          maxLength={2000}
        />

        <div className="grid gap-5 sm:grid-cols-2">
          <Input
            label="Lesson date"
            type="date"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            error={errors.date}
          />
          <StatusToggle value={status} onChange={setStatus} />
        </div>
      </Card>

      <Card className="space-y-4">
        <div className="flex items-center gap-2">
          <Video className="h-5 w-5 text-quran" aria-hidden />
          <h3 className="font-display text-lg font-bold text-night-900">
            Video
          </h3>
        </div>
        <Input
          label="YouTube link (optional)"
          placeholder="Paste any YouTube link"
          value={videoUrl}
          onChange={(e) => setVideoUrl(e.target.value)}
          error={
            errors.videoUrl ??
            (videoLooksInvalid
              ? "That doesn't look like a YouTube link."
              : undefined)
          }
        />
        {videoId && (
          <div className="flex items-center gap-3 rounded-sm border border-cream-200 bg-cream-50 p-3">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={youTubeThumbnail(videoId)}
              alt=""
              className="h-16 w-28 shrink-0 rounded object-cover"
            />
            <div className="min-w-0">
              <p className="flex items-center gap-1.5 text-sm font-semibold text-success">
                <CheckCircle2 className="h-4 w-4" aria-hidden />
                Video linked
              </p>
              <p className="truncate text-xs text-ink-soft">
                Video id: {videoId}
              </p>
            </div>
          </div>
        )}
      </Card>

      {isEdit ? (
        <QuizReadOnly lesson={lesson!} />
      ) : (
        <Card className="space-y-4">
          <label className="flex items-center justify-between gap-3">
            <span className="flex items-center gap-2">
              <ListChecks className="h-5 w-5 text-arabic" aria-hidden />
              <span className="font-display text-lg font-bold text-night-900">
                Quiz
              </span>
            </span>
            <span className="flex items-center gap-2 text-sm text-ink-soft">
              Add a quiz
              <input
                type="checkbox"
                checked={quizEnabled}
                onChange={(e) => setQuizEnabled(e.target.checked)}
                className="h-5 w-5 accent-gold-500"
              />
            </span>
          </label>

          {!quizEnabled ? (
            <p className="text-sm text-ink-soft">
              A lesson needs a video or a quiz. Turn this on to add questions.
            </p>
          ) : (
            <div className="space-y-5">
              <div className="w-40">
                <Input
                  label="Pass mark"
                  type="number"
                  min={1}
                  max={questions.length}
                  value={passMark}
                  onChange={(e) => setPassMark(e.target.value)}
                  error={errors.passMark}
                />
                <p className="mt-1 text-xs text-ink-soft">
                  Correct answers needed to pass (out of {questions.length}).
                </p>
              </div>

              {errors.quiz && (
                <p role="alert" className="text-sm text-error">
                  {errors.quiz}
                </p>
              )}

              {questions.map((q, qi) => (
                <QuestionEditor
                  key={q.key}
                  index={qi}
                  question={q}
                  canRemove={questions.length > 1}
                  onText={(t) => updateQuestion(qi, { text: t })}
                  onOption={(oi, t) => updateOption(qi, oi, t)}
                  onCorrect={(oi) => setCorrect(qi, oi)}
                  onRemove={() => removeQuestion(qi)}
                />
              ))}

              <Button type="button" variant="ghost" onClick={addQuestion}>
                <Plus className="h-4 w-4" aria-hidden />
                Add question
              </Button>
            </div>
          )}
        </Card>
      )}

      <div className="flex items-center justify-end gap-3">
        <Button
          type="button"
          variant="ghost"
          onClick={() => router.push("/dashboard/teacher/lessons")}
        >
          Cancel
        </Button>
        <Button type="submit" loading={pending}>
          {isEdit
            ? "Save changes"
            : status === "PUBLISHED"
              ? "Publish lesson"
              : "Save draft"}
        </Button>
      </div>
    </form>
  );
}

function StatusToggle({
  value,
  onChange,
}: {
  value: LessonStatus;
  onChange: (v: LessonStatus) => void;
}) {
  const opts: { v: LessonStatus; label: string }[] = [
    { v: "DRAFT", label: "Draft" },
    { v: "PUBLISHED", label: "Publish" },
  ];
  return (
    <div className="flex flex-col gap-1.5">
      <span className="text-sm font-medium text-night-900">Visibility</span>
      <div className="flex rounded-sm border border-cream-200 bg-cream-50 p-1">
        {opts.map((o) => (
          <button
            key={o.v}
            type="button"
            onClick={() => onChange(o.v)}
            aria-pressed={value === o.v}
            className={cn(
              "min-h-[36px] flex-1 rounded-[0.5rem] px-3 text-sm font-semibold transition-colors",
              value === o.v
                ? "bg-night-900 text-cream-50"
                : "text-ink-soft hover:text-night-900",
            )}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

function QuestionEditor({
  index,
  question,
  canRemove,
  onText,
  onOption,
  onCorrect,
  onRemove,
}: {
  index: number;
  question: LocalQuestion;
  canRemove: boolean;
  onText: (t: string) => void;
  onOption: (oi: number, t: string) => void;
  onCorrect: (oi: number) => void;
  onRemove: () => void;
}) {
  return (
    <fieldset className="rounded-md border border-cream-200 p-4">
      <div className="mb-3 flex items-center justify-between gap-3">
        <legend className="font-display text-sm font-bold text-night-900">
          Question {index + 1}
        </legend>
        {canRemove && (
          <button
            type="button"
            onClick={onRemove}
            className="inline-flex items-center gap-1 text-sm font-medium text-error hover:brightness-110"
          >
            <Trash2 className="h-4 w-4" aria-hidden />
            Remove
          </button>
        )}
      </div>

      <Input
        placeholder="Question text"
        value={question.text}
        onChange={(e) => onText(e.target.value)}
        aria-label={`Question ${index + 1} text`}
      />

      <p className="mt-3 mb-2 text-xs font-medium text-ink-soft">
        Tap the circle to mark the correct answer.
      </p>
      <div className="space-y-2">
        {question.options.map((o, oi) => (
          <label
            key={oi}
            className={cn(
              "flex items-center gap-3 rounded-sm border px-3 py-2 transition-colors",
              o.isCorrect ? "border-success bg-success/5" : "border-cream-200",
            )}
          >
            <input
              type="radio"
              name={`correct-${question.key}`}
              checked={o.isCorrect}
              onChange={() => onCorrect(oi)}
              className="h-5 w-5 accent-success"
              aria-label={`Mark option ${oi + 1} correct`}
            />
            <input
              type="text"
              value={o.text}
              onChange={(e) => onOption(oi, e.target.value)}
              placeholder={`Option ${oi + 1}`}
              aria-label={`Question ${index + 1} option ${oi + 1}`}
              className="min-h-9 w-full bg-transparent text-[15px] text-night-900 outline-none placeholder:text-ink-soft/60"
            />
          </label>
        ))}
      </div>
    </fieldset>
  );
}

function QuizReadOnly({ lesson }: { lesson: TeacherLessonDetail }) {
  const quiz = lesson.quiz;
  if (!quiz) {
    return (
      <Card className="space-y-2">
        <div className="flex items-center gap-2">
          <ListChecks className="h-5 w-5 text-arabic" aria-hidden />
          <h3 className="font-display text-lg font-bold text-night-900">
            Quiz
          </h3>
        </div>
        <p className="text-sm text-ink-soft">This lesson has no quiz.</p>
      </Card>
    );
  }

  return (
    <Card className="space-y-4">
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <ListChecks className="h-5 w-5 text-arabic" aria-hidden />
          <h3 className="font-display text-lg font-bold text-night-900">
            Quiz
          </h3>
        </div>
        <span className="text-sm text-ink-soft">
          Pass {quiz.passMark}/{quiz.totalQuestions}
        </span>
      </div>

      <div className="flex items-start gap-2 rounded-sm border border-cream-200 bg-cream-100 p-3 text-sm text-ink-soft">
        <Lock className="mt-0.5 h-4 w-4 shrink-0" aria-hidden />
        <p>
          {quiz.isEditable
            ? "Quizzes can't be changed after a lesson is created. You can still edit the title, date, description, video and visibility above."
            : "A student has already attempted this quiz, so it's locked to protect their results. Title, date, description, video and visibility can still change."}
        </p>
      </div>

      <ol className="space-y-3">
        {quiz.questions.map((q, qi) => (
          <li key={q.id} className="rounded-md border border-cream-200 p-4">
            <p className="mb-2 font-medium text-night-900">
              {qi + 1}. {q.text}
            </p>
            <ul className="space-y-1.5">
              {q.options.map((o) => (
                <li
                  key={o.id}
                  className={cn(
                    "flex items-center gap-2 rounded-sm px-2.5 py-1.5 text-sm",
                    o.isCorrect
                      ? "bg-success/10 font-semibold text-success"
                      : "text-ink-soft",
                  )}
                >
                  {o.isCorrect && (
                    <CheckCircle2 className="h-4 w-4" aria-hidden />
                  )}
                  {o.text}
                </li>
              ))}
            </ul>
          </li>
        ))}
      </ol>
    </Card>
  );
}

